    // @audit Passes same inflated value to AuctionAssist
    if (_auctionAssist != address(0)) {
        uint256 purchaseId_ = IAuctionAssist(_auctionAssist).recordPurchase(
            collection_, tokenId_, value_ // Inflated cost
        );
    }
}
```

