    // keep unlockTime in storage for next tx optimization
    depositor.unlockTime = uint40(Math.min(depositor.unlockTime, block.timestamp));
    depositors[msg.sender] = depositor; // SSTORE
    _burn(msg.sender, balance);
}
```

