    for (uint256 i; i < tokens.length; ) {
-       uint256 underlyingAmount = fmul(tokens[i].units, amount);
+       uint256 underlyingAmount = fmul(tokens[i].units, amount) + 1;
        IERC20(tokens[i].token).transferFrom(
            msg.sender,
            address(vault),
            underlyingAmount
        );

        unchecked {
            ++i;
