```solidity
function _median(uint[] memory array) public pure returns (uint) {
       _sort(array, 0, array.length);
       return
          array.length & uint256(1) == 0
               ? ((array[(array.length >> 1) - 1] +
                   array[array.length >> 1]) >> 1)
