        if (batch.amount > burnAmount) {
            batch.amount -= burnAmount;
            remaining -= burnAmount;
        } else {
            remaining -= batch.amount;
            ownerBatches[from][i] = ownerBatches[from][len - 1];
            ownerBatches[from].pop();
            delete batches[batchId];
            len--;
            continue;
        }
    }
    unchecked {
        ++i;
    }
}
```

