  swingTraderManager.toggleTraderActive(3);
  assertEq(swingTraderManager.activeTraders(2),3);
  assertEq(swingTraderManager.activeTraders(3),3); // @audit:activeTraders[2] = activeTraders[3] = 3
  vm.prank(admin);
  swingTraderManager.toggleTraderActive(3);
  assertEq(swingTraderManager.activeTraders(2),3);
}
```

