        uint256 attackerGoatProfit = goat.balanceOf(attacker) -
            initialGoatAmount;
        assertEq(attackerWethProfit, 399855575210658419);
        assertEq(attackerGoatProfit, 453187161321825804);
        vm.stopPrank();
    }
}
