    (o.totalAmt - protocolfee - o.exchange.paymentAmt - o.prePayment.paymentAmt - o.refererrAmt) *
        amount -
        p.paymentAmt,
    msg.sender
);
} else {
    payEther(
        (o.totalAmt - protocolfee - o.exchange.paymentAmt - o.prePayment.paymentAmt) * amount - p.paymentAmt,
        msg.sender
    );
```

