        params.lienRequest.v,
        params.lienRequest.r,
        params.lienRequest.s
    );
    if (
        (recovered != owner() && recovered != s.delegate) ||
        recovered == address(0)
    ) {
        revert IVaultImplementation.InvalidRequest(
            InvalidRequestReason.INVALID_SIGNATURE
        );
    }
}
