    uint256 storedMaturity = accountStorage.maturity;

    int256 accountDebtOne =
        -int256(uint256(accountStorage.accountDebtOne));
    int256 accountDebtTwo =
        -int256(uint256(accountStorage.accountDebtTwo));

    if (storedMaturity == 0) {
        // Handles edge condition where an account is holding vault shares past maturity without
        // any debt position.
        require(accountDebtOne == 0 && accountDebtTwo == 0);
    } else {
```

In addition, the vault account data is corrupted as there is a secondary debt without maturity, which might affect internal accounting and tracking.

recommendation:
Fetch the prime rate of both secondary currencies because they are both needed within the updateAccountSecondaryDebt function when converting debt storage to underlying.

```solidity
function _reduceAccountDebt(
    VaultConfig memory vaultConfig,
    VaultState memory vaultState,
    VaultAccount memory vaultAccount,
    PrimeRate memory primeRate,
    uint256 currencyIndex,
    int256 depositUnderlyingInternal,
    bool checkMinBorrow
) private {
    if (currencyIndex == 0) {
        vaultAccount.updateAccountDebt(vaultState, depositUnderlyingInternal, 0);
        vaultState.setVaultState(vaultConfig);
    } else {
        // Only set one of the prime rates, the other prime rate is not used since
        // the net debt amount is set to zero
        PrimeRate[2] memory pr;
        pr = VaultSecondaryBorrow.getSecondaryPrimeRateStateful(vaultConfig);

        VaultSecondaryBorrow.updateAccountSecondaryDebt(
            vaultConfig,
            vaultAccount.account,
            vaultAccount.maturity,
            currencyIndex == 1 ? depositUnderlyingInternal : 0,
            currencyIndex == 2 ? depositUnderlyingInternal : 0,
            pr,
            checkMinBorrow
        );
    }
}
```

description:
When `isolateLiquidate(supplyAsCollateral=false)` is executed, finally `erc721DecreaseIsolateSupplyOnLiquidate()` will be executed and the NFT will be transferred to the user.

```solidity
function erc721DecreaseIsolateSupplyOnLiquidate(
  DataTypes.AssetData storage assetData,
  uint256[] memory tokenIds
) internal {
  for (uint256 i = 0; i < tokenIds.length; i++) {
    DataTypes.ERC721TokenData storage tokenData = assetData.erc721TokenData[tokenIds[i]];
    require(tokenData.supplyMode == Constants.SUPPLY_MODE_ISOLATE, Errors.INVALID_SUPPLY_MODE);

    assetData.userScaledIsolateSupply[tokenData.owner] -= 1;

    tokenData.owner = address(0);
    tokenData.supplyMode = 0;
    //missing tokenData.lockerAddr = address(0);
  }

  assetData.totalScaledIsolateSupply -= tokenIds.length;
}
```

We know from the above code that this method does not clear the `tokenData.lockerAddr`, so now `tokenData` is:

  * erc721TokenData[NFT_1].owner = 0
  * erc721TokenData[NFT_1].supplyMode = 0
  * erc721TokenData[NFT_1].lockerAddr = `address(poolManager)`

User Alice has NFT_1; then Alice executes `BVault.depositERC721(NFT_1, supplyMode = SUPPLY_MODE_CROSS)` will succeed, `deposit()` does not check `lockerAddr`.

So `tokenData` becomes:

  * erc721TokenData[NFT_1].owner = Alice
  * erc721TokenData[NFT_1].supplyMode = `SUPPLY_MODE_CROSS`
  * erc721TokenData[NFT_1].lockerAddr = `address(poolManager)` - not changed.

After that the user’s NFT_1 will be locked because `withdrawERC721()` `->` `validateWithdrawERC721()` will check that `lockerAddr` must be `address(0)`:

```solidity
function validateWithdrawERC721(
...
  for (uint256 i = 0; i < inputParams.tokenIds.length; i++) {
    DataTypes.ERC721TokenData storage tokenData = VaultLogic.erc721GetTokenData(assetData, inputParams.tokenIds[i]);
    require(tokenData.owner == inputParams.onBehalf, Errors.INVALID_CALLER);
    require(tokenData.supplyMode == inputParams.supplyMode, Errors.INVALID_SUPPLY_MODE);

    require(tokenData.lockerAddr == address(0), Errors.ASSET_ALREADY_LOCKED_IN_USE);
  }
}
```

Other `Isolate` methods cannot be operated either.

Note: `erc721DecreaseIsolateSupply()` is similar.

recommendation:
```solidity
function erc721DecreaseIsolateSupplyOnLiquidate(
  DataTypes.AssetData storage assetData,
  uint256[] memory tokenIds
) internal {
  for (uint256 i = 0; i < tokenIds.length; i++) {
    DataTypes.ERC721TokenData storage tokenData = assetData.erc721TokenData[tokenIds[i]];
    require(tokenData.supplyMode == Constants.SUPPLY_MODE_ISOLATE, Errors.INVALID_SUPPLY_MODE);

    assetData.userScaledIsolateSupply[tokenData.owner] -= 1;

    tokenData.owner = address(0);
    tokenData.supplyMode = 0;
    tokenData.lockerAddr = address(0);
  }

  assetData.totalScaledIsolateSupply -= tokenIds.length;
}

function erc721DecreaseIsolateSupply(
  DataTypes.AssetData storage assetData,
  address user,
  uint256[] memory tokenIds
) internal {
  for (uint256 i = 0; i < tokenIds.length; i++) {
    DataTypes.ERC721TokenData storage tokenData = assetData.erc721TokenData[tokenIds[i]];
    require(tokenData.supplyMode == Constants.SUPPLY_MODE_ISOLATE, Errors.INVALID_SUPPLY_MODE);

    tokenData.owner = address(0);
    tokenData.supplyMode = 0;
    tokenData.lockerAddr = address(0);
  }

  assetData.totalScaledIsolateSupply -= tokenIds.length;
  assetData.userScaledIsolateSupply[user] -= tokenIds.length;
}
```

description:
When the rule requires the previous moving averages in UpdateRule::CalculateNewWeights, the movingAverages[pool] array length is twice the number of assets. However, when unpacking it using the QuantAMMStorage::quantAMMUnpack128Array function, the amount of data requested is the same as the number of assets, i.e, half of the original length, causing the process to revert with an array out-of-bounds access error.

This issue causes rules like MinimumVarianceUpdateRule to permanently revert.

QuantAMMStorage::_quantAMMUnpack128Array function is used to unpack n/2 256 bit integers into n 128 bit integers (as stated in the natspec). By design, this function requires the target array to be exactly the same length as the source array before being packed, otherwise it will revert with an array out-of-bounds access error, as can be seen in the function code.

```solidity
QuantAMMStorage.sol

    function _quantAMMUnpack128Array(
        int256[] memory _sourceArray,
        uint _targetArrayLength
    ) internal pure returns (int256[] memory targetArray) {
        require(_sourceArray.length * 2 >= _targetArrayLength, "SRC!=TGT");
        targetArray = new int256[](_targetArrayLength);
        uint targetIndex;
        uint sourceArrayLengthMinusOne = _sourceArray.length - 1;
        bool divisibleByTwo = _targetArrayLength % 2 == 0;

        // @audit - _sourceArray.length is the bound of the loop, wich means that all the elements in the source array must be unpacked,
        // i.e., the function does not admit to unpack less elements than the packed.
        // @audit note * - this can be seen as a design choice or as a bug, depending on the preferences of the protocol team.
        // In this report, given the function description this is considered a design choice and the issue is in the way the function is used.
        for (uint i; i < _sourceArray.length; ) {
            targetArray[targetIndex] = _sourceArray[i] >> 128;
            unchecked {
                ++targetIndex;
            }
            if ((!divisibleByTwo && i < sourceArrayLengthMinusOne) || divisibleByTwo) {
                targetArray[targetIndex] = int256(int128(_sourceArray[i]));
            }
            unchecked {
                ++i;
                ++targetIndex;
            }
        }

        if (!divisibleByTwo) {
            targetArray[targetArrayLength - 1] = int256(int128(_sourceArray[sourceArrayLengthMinusOne]));
        }
    }
```

On the other hand, the UpdateRule::CalculateNewWeights function is used to calculate the new weights of the pool. When previous data is required, the movingAverages[pool] array length is twice the number of assets. This array is packed taking its full length (2 * numberOfAssets), however it is unpacked as if its length were the same as the number of assets in the pool. In this case, the discrepancy between the packing and unpacking length causes the process to revert because the QuantAMMStorage::quantAMMUnpack128Array function does not allow to unpack fewer elements than originally packed.

```solidity
UpdateRule.sol

    function CalculateNewWeights(
        int256[] calldata _prevWeights,
        int256[] calldata _data,
        address _pool,
        int256[][] calldata _parameters,
        uint64[] calldata _lambdaStore,
        uint64 _epsilonMax,
        uint64 _absoluteWeightGuardRail
    ) external returns (int256[] memory updatedWeights) {
        require(msg.sender == updateWeightRunner, "UNAUTH_CALC");

        QuantAMMUpdateRuleLocals memory locals;

        locals.numberOfAssets = _prevWeights.length;
        locals.nMinusOne = locals.numberOfAssets - 1;
        locals.lambda = new int128[](_lambdaStore.length);

        for (locals.i; locals.i < locals.lambda.length; ) {
            locals.lambda[locals.i] = int128(uint128(_lambdaStore[locals.i]));
            unchecked {
                ++locals.i;
            }
        }

        locals.requiresPrevAverage = requiresPrevMovingAverage() == REQPREVMAVGVAL;
        locals.intermediateMovingAverageStateLength = locals.numberOfAssets;

        if (locals.requiresPrevAverage) {
            unchecked {
                locals.intermediateMovingAverageStateLength *= 2;
            }
        }

        locals.currMovingAverage = new int256[]();
        locals.updatedMovingAverage = new int256[](locals.numberOfAssets);

        // @audit - if previous moving averages are required, length of this array is twice the number of assets
        locals.calculationMovingAverage = new int256[]();

        // @audit - In all cases locals.currMovingAverage array length is the same as the number of assets
        // furthermore, the number of assets is passed as the parameter in the function
        locals.currMovingAverage = quantAMMUnpack128Array(movingAverages[pool], locals.numberOfAssets);

        ... snip

        // @audit - if previous moving averages are required, movingAverages[_pool] array is filled by packing
        // the locals.calculationMovingAverage, which length is twice the number of assets.
        // As in all cases only locals.numberOfAssets is passed to the unpack function, the process will revert because of
        // the difference between the source and target arrays length
        if (locals.requiresPrevAverage) {
            movingAverages[pool] = quantAMMPack128Array(locals.calculationMovingAverage);
        }

        QuantAMMPoolParameters memory poolParameters;
        poolParameters.lambda = locals.lambda;
        poolParameters.movingAverage = locals.calculationMovingAverage;
        poolParameters.pool = _pool;

        //calling the function in the derived contract specific to the specific rule
        locals.unGuardedUpdatedWeights = getWeights(prevWeights, data, parameters, poolParameters);

        //Guard weights is done in the base contract so regardless of the rule the logic will always be executed
        updatedWeights = _guardQuantAMMWeights(
            locals.unGuardedUpdatedWeights,
            _prevWeights,
            int128(uint128(_epsilonMax)),
            int128(uint128(_absoluteWeightGuardRail))
        );
    }
```

Impact: High

Likelihood: Medium

recommendation:
It is required to modify the CalculateNewWeights function to pack the correct array. As movingAverages[_pool] does not require to contain the previous values, a valid solution is the following:

```diff
UpdateRule.sol

    function CalculateNewWeights(
        int256[] calldata _prevWeights,
        int256[] calldata _data,
        address _pool,
        int256[][] calldata _parameters,
        uint64[] calldata _lambdaStore,
        uint64 _epsilonMax,
        uint64 _absoluteWeightGuardRail
    ) external returns (int256[] memory updatedWeights) {
        require(msg.sender == updateWeightRunner, "UNAUTH_CALC");

        QuantAMMUpdateRuleLocals memory locals;

        locals.numberOfAssets = _prevWeights.length;
        locals.nMinusOne = locals.numberOfAssets - 1;
        locals.lambda = new int128[](_lambdaStore.length);

        ... snip

        //because of mixing of prev and current if the numassets is odd it is makes normal code unreadable to do inline
        //this means for rules requiring prev moving average there is an addition SSTORE and local packed array
        if (locals.requiresPrevAverage) {
            movingAverages[pool] = quantAMMPack128Array(locals.calculationMovingAverage);
            movingAverages[pool] = quantAMMPack128Array(locals.updatedMovingAverage);
        }

        QuantAMMPoolParameters memory poolParameters;
        poolParameters.lambda = locals.lambda;
        poolParameters.movingAverage = locals.calculationMovingAverage;
        poolParameters.pool = _pool;

        //calling the function in the derived contract specific to the specific rule
        locals.unGuardedUpdatedWeights = getWeights(prevWeights, data, parameters, poolParameters);

        //Guard weights is done in the base contract so regardless of the rule the logic will always be executed
        updatedWeights = _guardQuantAMMWeights(
            locals.unGuardedUpdatedWeights,
            _prevWeights,
            int128(uint128(_epsilonMax)),
            int128(uint128(_absoluteWeightGuardRail))
        );
    }
```

**Proof of Concept:**
```solidity
To reproduce the issue, it is possible to use the existent tests with slightly modifications. The steps to follow are: Set the UpdateRule::_requiresPrevMovingAverage function to return 1, to indicate that previous moving averages are required Take a test and make sure to call the UpdateRule::CalculateNewWeights function two times. This is important as in the first call all the initialized variables are 'adjusted' to guarantee everything works fine, but in the second time all of them are modified and become more 'realistic'.

Step 1. Set the UpdateRule::_requiresPrevMovingAverage function to return 1 It is necessary to modify the MockUpdateRule::_requiresPrevMovingAverage function.

```diff
MockUpdateRule.sol

    function _requiresPrevMovingAverage() internal pure virtual override returns (uint16) {
        return 0;
        return 1;
    }
```

\* Note. After this modification, the issue can be seen when executing the UpdateRule.t.sol::testUpdateRuleMovingAverageStorage test. It will fail because of the same root cause explained in this report.

Step 2. Take a test and make sure to call the UpdateRule::CalculateNewWeights function two times Lets take the testUpdateRuleAuthCalc test located in the test/foundry/rules/UpdateRule.t.sol file. After the call to the CalculateNewWeights function, add a second call to the same function and execute the test.

```diff
UpdateRule.t.sol

    function testUpdateRuleAuthCalc() public {
        vm.startPrank(owner);
         // Define local variables for the parameters

        ...snip

        //does not revert
        updateRule.CalculateNewWeights(
        prevWeights,
        data,
        address(mockPool),
        parameters,
        lambdas,
        uint64(uint256(epsilonMax)),
        uint64(0.2e18));

        // @audit - the same parameters are ok
        //does revert
        updateRule.CalculateNewWeights(
            prevWeights,
            data,
            address(mockPool),
            parameters,
            lambdas,
            uint64(uint256(epsilonMax)),
            uint64(0.2e18));

        vm.stopPrank();
    }
```

When executing the test, process will revert with the array out-of-bounds access error, causing a permanent denial of service.
```

It is recommended to implement a check within the [memorializePositions function](https://github.com/code-423n4/2023-05-ajna/blob/276942bc2f97488d07b887c8edceaaab7a5c3964/ajna-core/src/PositionManager.sol#L170) that will ensure that a user has specified an allowance at least equal to their lp balance at each respective index, reverting with a custom error if not true. For example, the function could be refactored to the following where the mentioned check is implemented [here](https://github.com/code-423n4/2023-05-ajna/blob/276942bc2f97488d07b887c8edceaaab7a5c3964/ajna-core/src/PositionManager.sol#L189):
```solidity
    function memorializePositions(
        MemorializePositionsParams calldata params_
    ) external override {
        EnumerableSet.UintSet storage positionIndex = positionIndexes[params_.tokenId];

        IPool   pool  = IPool(poolKey[params_.tokenId]);
        address owner = ownerOf(params_.tokenId);

        uint256 indexesLength = params_.indexes.length;
        uint256 index;

        for (uint256 i = 0; i < indexesLength; ) {
            index = params_.indexes[i];

            // record bucket index at which a position has added liquidity
            // slither-disable-next-line unused-return
            positionIndex.add(index);

            (uint256 lpBalance, uint256 depositTime) = pool.lenderInfo(index, owner);

            // check that specified allowance is at least equal to the lp balance
            uint256 allowance = pool.lpAllowance(index, address(this), owner);

            if(allowance < lpBalance) revert AllowanceTooLow();

            Position memory position = positions[params_.tokenId][index];

            // check for previous deposits
            if (position.depositTime != 0) {
                // check that bucket didn't go bankrupt after prior memorialization
                if (_bucketBankruptAfterDeposit(pool, index, position.depositTime)) {
                    // if bucket did go bankrupt, zero out the LP tracked by position manager
                    position.lps = 0;
                }
            }

            // update token position LP
            position.lps += lpBalance;
            // set token's position deposit time to the original lender's deposit time
            position.depositTime = depositTime;

            // save position in storage
            positions[params_.tokenId][index] = position;

            unchecked { ++i; }
        }

        // update pool LP accounting and transfer ownership of LP to PositionManager contract
        pool.transferLP(owner, address(this), params_.indexes);

        emit MemorializePosition(owner, params_.tokenId, params_.indexes);
    }
```

**Proof of Concept:**
```solidity
The described vulnerability occurs when a lender specifies allowances for the PositionManager contract that are less than their lp balance for each respective index through the [increaseLPAllowance function](https://github.com/code-423n4/2023-05-ajna/blob/276942bc2f97488d07b887c8edceaaab7a5c3964/ajna-core/src/base/Pool.sol#L455) and then invokes the [memorializePositions function](https://github.com/code-423n4/2023-05-ajna/blob/276942bc2f97488d07b887c8edceaaab7a5c3964/ajna-core/src/PositionManager.sol#L170). The result of this is that the user’s lp balance tracked by the [PositionManager’s state](https://github.com/code-423n4/2023-05-ajna/blob/276942bc2f97488d07b887c8edceaaab7a5c3964/ajna-core/src/PositionManager.sol#L202) will increment by the position’s balance while the lp balance tracked by the [Pool’s state](https://github.com/code-423n4/2023-05-ajna/blob/276942bc2f97488d07b887c8edceaaab7a5c3964/ajna-core/src/libraries/external/LPActions.sol#L260) will only decrement by the specified allowance. A user can repeat this process through multiple iterations until their respective lp balances with the Pool contract are 0 which will exponentially increase the value of their position. Please see the following test case for a POC simulating the effect of this described vulnerability on a user’s position:
```solidity
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.14;

import "forge-std/console.sol";

import {Base64} from "@base64-sol/base64.sol";

import "tests/forge/unit/PositionManager.t.sol";

/**
 *  @title  Proof of Concept
 *  @notice Simulates the effect of the described vulnerability where a user
 *          can exponentially increase the value of their position by:
 *          1- only approving the `PositionManager` for a min amount of their position
 *          2- invoking 'memorializePositions' on their position's respective NFT
 *          3- repeating these steps until their respective position's Pool lp balance is 0
 *  @dev    This test case can be implemented and run from the ajna-core/tests/forge directory
 */
contract POC is PositionManagerERC20PoolHelperContract {
