description:
In order to incentivize users to stake the ETH earnings in earningReinvest, maxEarning is reduced to keep the ﬁnancial stability.
```solidity
function earningReinvest(
    bool isEth_,
    address payable poolOwner_,
    uint duration_,
    uint amount_,
    // address[] memory pulledPoolOwners_,
    uint minSPercent_,
    uint poolConfigCode_
)
external
{
    address account = msg.sender;
    if (isEth_) {
        LLocker.SLock memory oldLockData = _eLocker.getLockData(account, poolOwner_);
        uint realDuration = duration_ + LLocker.restDuration(oldLockData);
        if (realDuration > _maxDuration) {
            realDuration = _maxDuration;
        }
        uint maxEarning = _eEarning.maxEarningOf(account);
        maxEarning -= amount_ * realDuration / _maxDuration;
        _eEarning.updateMaxEarning(account, maxEarning);
    }
    earningWithdraw(isEth_, amount_, payable(address(this)), 0);
    _stake(isEth_, account, poolOwner_, duration_, minSPercent_, poolConfigCode_);
}
```
However, since earning.withdraw calls shareCommission, which updates maxEarning, the previous reduction of maxEarning will not work.
```solidity
function earningWithdraw(
    bool isEth_,
    uint amount_,
    address payable dest_,
    uint minEthA_
    // address[] memory pulledPoolOwners_
)
public
{
    address account = msg.sender;
    // earningPulls(account, pulledPoolOwners_, account);
    IEarning earning = isEth_ ? _eEarning : _dEarning;
    earning.withdraw(account, amount_, address(this));
    // ...
}
function withdraw(
    address account_,
    uint amount_,
    address dest_
)
external
onlyAdmin
{
    shareCommission(account_);
    // ...
    if (_sharedA[account_] > _maxEarningOf[account_]) {
        _updateMaxEarning(account_, _sharedA[account_]);
    }
}
```
Consider maxEarning = 1000, _sharedA = 1000, balanceOf = 1100 (100 no shareCommission, sPercent=10%), fs = 1. The user earningReinvest 1000 with maxDuration, and maxEarning is reduced to 0. However, when earning.withdraw calls shareCommission, _sharedA is updated to 1000 + 100 * 0.9 = 1090, and _maxEarningOf changes from 0 to 1090. At the end of _stake, fs = ((1090 - 1000) + 1000 * 2%) / 1090 = 0.1, this reduces the poolOwner's score to 1/10.

recommendation:
The ﬁx will be to reduce maxEarning after withdraw:
```solidity
function earningReinvest(
    bool isEth_,
    address payable poolOwner_,
    uint duration_,
    uint amount_,
    // address[] memory pulledPoolOwners_,
    uint minSPercent_,
    uint poolConfigCode_
)
external
{
    address account = msg.sender;
    earningWithdraw(isEth_, amount_, payable(address(this)), 0);
    if (isEth_) {
        LLocker.SLock memory oldLockData = _eLocker.getLockData(account, poolOwner_);
        uint realDuration = duration_ + LLocker.restDuration(oldLockData);
        if (realDuration > _maxDuration) {
            realDuration = _maxDuration;
        }
        uint maxEarning = _eEarning.maxEarningOf(account);
        maxEarning -= amount_ * realDuration / _maxDuration;
        _eEarning.updateMaxEarning(account, maxEarning);
    }
    _stake(isEth_, account, poolOwner_, duration_, minSPercent_, poolConfigCode_);
}
```

description:
The Reth derivative contract implements the `poolPrice` function to get the spot price of the derivative asset using a Uniswap V3 pool. The function queries the pool to fetch the `sqrtPriceX96` and does the following calculation:

```solidity
function poolPrice() private view returns (uint256) {
    address rocketTokenRETHAddress = RocketStorageInterface(
        ROCKET_STORAGE_ADDRESS
    ).getAddress(
            keccak256(
                abi.encodePacked("contract.address", "rocketTokenRETH")
            )
        );
    IUniswapV3Factory factory = IUniswapV3Factory(UNI_V3_FACTORY);
    IUniswapV3Pool pool = IUniswapV3Pool(
        factory.getPool(rocketTokenRETHAddress, W_ETH_ADDRESS, 500)
    );
    (uint160 sqrtPriceX96, , , , , , ) = pool.slot0();
    return (sqrtPriceX96 * (uint(sqrtPriceX96)) * (1e18)) >> (96 * 2);
}
```

The main issue here is that the multiplications in the expression `sqrtPriceX96 * (uint(sqrtPriceX96)) * (1e18)` may eventually overflow. This case is taken into consideration by the implementation of the [OracleLibrary.getQuoteAtTick](https://docs.uniswap.org/contracts/v3/reference/periphery/libraries/OracleLibrary#getquoteattick) function which is part of the Uniswap V3 periphery set of contracts.

```solidity
function getQuoteAtTick(
    int24 tick,
    uint128 baseAmount,
    address baseToken,
    address quoteToken
) internal pure returns (uint256 quoteAmount) {
    uint160 sqrtRatioX96 = TickMath.getSqrtRatioAtTick(tick);

    // Calculate quoteAmount with better precision if it doesn't overflow when multiplied by itself
    if (sqrtRatioX96 <= type(uint128).max) {
        uint256 ratioX192 = uint256(sqrtRatioX96) * sqrtRatioX96;
        quoteAmount = baseToken < quoteToken
            ? FullMath.mulDiv(ratioX192, baseAmount, 1 << 192)
            : FullMath.mulDiv(1 << 192, baseAmount, ratioX192);
    } else {
        uint256 ratioX128 = FullMath.mulDiv(sqrtRatioX96, sqrtRatioX96, 1 << 64);
        quoteAmount = baseToken < quoteToken
            ? FullMath.mulDiv(ratioX128, baseAmount, 1 << 128)
            : FullMath.mulDiv(1 << 128, baseAmount, ratioX128);
    }
}
```

Note that this implementation guards against different numerical issues. In particular, the if in line 58 checks for a potential overflow of `sqrtRatioX96` and switches the implementation to avoid the issue.

recommendation:
The `poolPrice` function can delegate the calculation directly to the [OracleLibrary.getQuoteAtTick](https://docs.uniswap.org/contracts/v3/reference/periphery/libraries/OracleLibrary#getquoteattick) function of the `v3-periphery` package:

```solidity
function poolPrice() private view returns (uint256) {
    address rocketTokenRETHAddress = RocketStorageInterface(
        ROCKET_STORAGE_ADDRESS
    ).getAddress(
            keccak256(
                abi.encodePacked("contract.address", "rocketTokenRETH")
            )
        );
    IUniswapV3Factory factory = IUniswapV3Factory(UNI_V3_FACTORY);
    IUniswapV3Pool pool = IUniswapV3Pool(
        factory.getPool(rocketTokenRETHAddress, W_ETH_ADDRESS, 500)
    );
    (, int24 tick, , , , , ) = pool.slot0();
    return OracleLibrary.getQuoteAtTick(tick, 1e18, rocketTokenRETHAddress, W_ETH_ADDRESS);
}
```

