}
```
```solidity
uint256 internal constant INITIAL_REWARD_INDEX = 1;
```
Impact: since rewardTokens list is append only and _setPostExpiryData() can't be run again, all the rewards within userRewardOwed balances will be permanently frozen in the YT contract.  
Likelihood: Low (SY with an expanding reward token list and not yet added reward token is a prerequisite) + Impact: Critical (most of the rewards are end up frozen) = Severity: High.

recommendation:
```solidity
function _distributeRewardsPrivate(address user, address[] memory tokens, uint256[] memory indexes) private {
    assert(user != address(0) && user != address(this));
    uint256 userShares = _rewardSharesUser(user);
    for (uint256 i = 0; i < tokens.length; ++i) {
        address token = tokens[i];
        uint256 index = indexes[i];
        uint256 userIndex = userReward[token][user].index;
        if (userIndex == 0) {
            userIndex = INITIAL_REWARD_INDEX.Uint128();
        }
        if (userIndex == index || index == 0) continue;
        uint256 deltaIndex = index - userIndex;
        uint256 rewardDelta = userShares.mulDown(deltaIndex);
        uint256 rewardAccrued = userReward[token][user].accrued + rewardDelta;
        userReward[token][user] = UserReward({index: index.Uint128(), accrued: rewardAccrued.Uint128()});
    }
}
```

description:
Any malicious seller can copy the name, symbol and description of any previously listed asset and list it at a 1 wei lower price. In the case of this NFT being selected to be purchased by the system, this malicious seller will guarantee that their asset with lower price would be selected. This will lead to user's copying previously listed NFT's and listing it at a lower price, in a way creating a price race to the bottom.

Any seller can list an NFT with the list function.
```solidity
function list(string calldata name, string calldata symbol, bytes calldata desc, uint256 price, address _buyer)
    external
{
    BuyerAgent buyer = BuyerAgent(_buyer);
    (uint256 round, BuyerAgent.Phase phase,) = buyer.getRoundPhase();

    // buyer must be in the sell phase
    if (phase != BuyerAgent.Phase.Sell) {
        revert BuyerAgent.InvalidPhase(phase, BuyerAgent.Phase.Sell);
    }
    // asset count must not exceed maxAssetCount
    if (getCurrentMarketParameters().maxAssetCount == assetsPerBuyerRound[_buyer][round].length) {
        revert AssetLimitExceeded(getCurrentMarketParameters().maxAssetCount);
    }

    // all is well, create the asset & its listing
    address asset = address(swanAssetFactory.deploy(name, symbol, _desc, msg.sender));
    listings[asset] = AssetListing({
        createdAt: block.timestamp,
        royaltyFee: buyer.royaltyFee(),
        price: _price,
        seller: msg.sender,
        status: AssetStatus.Listed,
        buyer: _buyer,
        round: round
    });

    // add this to list of listings for the buyer for this round
    assetsPerBuyerRound[_buyer][round].push(asset);

    // transfer royalties
    transferRoyalties(listings[asset]);

    emit AssetListed(msg.sender, asset, _price);
}
```
As observed, this function take the name, symbol, desc and price parameters. Function then deploys a new NFT with these parameters and mints 1 NFT to the msg.sender.
```solidity
contract SwanAssetFactory {
    /// @notice Deploys a new SwanAsset token.
    function deploy(string memory name, string memory symbol, bytes memory description, address owner)
        external
        returns (SwanAsset)
    {
        return new SwanAsset(name, symbol, description, owner, msg.sender);
    }
}

/// @notice SwanAsset is an ERC721 token with a single token supply.
contract SwanAsset is ERC721, Ownable {
    /// @notice Creation time of the token
    uint256 public createdAt;
    /// @notice Description of the token
    bytes public description;

    /// @notice Constructor sets properties of the token.
    constructor(
        string memory _name,
        string memory _symbol,
        bytes memory _description,
        address _owner,
        address _operator
    ) ERC721(name, symbol) Ownable(_owner) {
        description = _description;
        createdAt = block.timestamp;

        // owner is minted the token immediately
        ERC721.mint(owner, 1);

        // Swan (operator) is approved to by the owner immediately.
        ERC721.setApprovalForAll(owner, _operator, true);
    }
}
```
As observed, there are no checks for "clone" inputs. Meaning that any malicious seller can copy the parameters of any previously listed NFT and list it at a 1 wei lower price. In case of an NFT with these parameters being selected, the malicious user would guarantee their NFT at lower price would be selected, putting no work in creating an original NFT and simply copying previously deployed NFTs. This will create a price race to the bottom among users where users would list the NFT with same parameters, each one putting it at 1 wei lower price, breaking the protocols intended use. The AI agents seeing all or most of the NFT's listed having the same properties would choose to purchase the NFT with these properties at the lowest price.

Impact: High, this vulnerability will break the intended use of the protocol. It will create a price race to the bottom where users list the NFT with same name, symbol and description, each user listing it at 1 wei lower price to ensure their NFT would be chosen by the system. Likelihood: Low, There are no guarantees that this NFT would be chosen by the system but noticing copies of the same NFTs can manipulate the LLM into thinking this is a good purchase.

recommendation:
Implement a for loop in the list function that will check the NFT that is being listed against the already listed NFTs. An example for loop is shown below. Keep in mind that this implementation might cost a lot of gas if there are too many listed NFTs.
```solidity
address[] memory assets = assetsPerBuyerRound[buyer][round];
for (uint256 i = 0; i < assets.length; i++) {
    IERC721 asset = IERC721(assets[i]);

    // Retrieve the name and symbol from the asset contract
    string memory assetName = asset.name();
    string memory assetSymbol = asset.symbol();

    // Check if both name and symbol match
    if (keccak256(bytes(assetName)) == keccak256(bytes(targetName)) &&
        keccak256(bytes(assetSymbol)) == keccak256(bytes(targetSymbol))) {
        revert("Asset with matching name and symbol already exists in this round");
    }
}
```

description:
1. `EIP712MetaTransaction` is a utils contract that intended to be inherited by concrete (actual) contracts, therefore. it’s initializer function should not use the `initializer` modifier, instead, it should use `onlyInitializing` modifier. See the implementation of [openzeppelin `EIP712Upgradeable` initializer function](https://github.com/OpenZeppelin/openzeppelin-contracts-upgradeable/blob/v4.5.1/contracts/utils/cryptography/draft-EIP712Upgradeable.sol#L48-L57).

[EIP712MetaTransaction.sol#L102-L114](https://github.com/code-423n4/2022-03-rolla/blob/efe4a3c1af8d77c5dfb5ba110c3507e67a061bdd/quant-protocol/contracts/utils/EIP712MetaTransaction.sol#L102-L114)

```solidity
/// @notice initialize method for EIP712Upgradeable
/// @dev called once after initial deployment and every upgrade.
/// @param _name the user readable name of the signing domain for EIP712
/// @param _version the current major version of the signing domain for EIP712
function initializeEIP712(string memory _name, string memory _version)
    public
    initializer
{
    name = _name;
    version = _version;

    __EIP712_init(_name, _version);
}
```

Otherwise, when the concrete contract’s initializer function (with a `initializer` modifier) is calling EIP712MetaTransaction’s initializer function, it will be mistok as reentered and so that it will be reverted (unless in the context of a constructor, e.g. Using @openzeppelin/hardhat-upgrades `deployProxy()` to initialize).

```solidity
/**
 * @dev Modifier to protect an initializer function from being invoked twice.
 */
modifier initializer() {
    // If the contract is initializing we ignore whether _initialized is set in order to support multiple
    // inheritance patterns, but we only do this in the context of a constructor, because in other contexts the
    // contract may have been reentered.
    require(_initializing ? _isConstructor() : !_initialized, "Initializable: contract is already initialized");

    bool isTopLevelCall = !_initializing;
    if (isTopLevelCall) {
        _initializing = true;
        _initialized = true;
    }

    _;

    if (isTopLevelCall) {
        _initializing = false;
    }
}
```

See also: <https://github.com/OpenZeppelin/openzeppelin-contracts-upgradeable/releases/tag/v4.4.1>

2. `initializer` can only be called once, it can not be “called once after every upgrade”.

[EIP712MetaTransaction.sol#L102-L114](https://github.com/code-423n4/2022-03-rolla/blob/efe4a3c1af8d77c5dfb5ba110c3507e67a061bdd/quant-protocol/contracts/utils/EIP712MetaTransaction.sol#L102-L114)

```solidity
/// @notice initialize method for EIP712Upgradeable
/// @dev called once after initial deployment.
/// @param _name the user readable name of the signing domain for EIP712
/// @param _version the current major version of the signing domain for EIP712
function initializeEIP712(string memory _name, string memory _version)
    public
    initializer
{
    name = _name;
    version = _version;

    __EIP712_init(_name, _version);
}
```

3. A utils contract that is not expected to be deployed as a standalone contract should be declared as `abstract`. It’s `initializer` function should be `internal`.

See the implementation of [openzeppelin `EIP712Upgradeable`](https://github.com/OpenZeppelin/openzeppelin-contracts-upgradeable/blob/v4.5.1/contracts/utils/cryptography/draft-EIP712Upgradeable.sol#L28).

```solidity
abstract contract EIP712Upgradeable is Initializable {
    // ...
}
```

recommendation:
Change to:

```solidity
abstract contract EIP712MetaTransaction is EIP712Upgradeable {
    // ...
}

/// @notice initialize method for EIP712Upgradeable
/// @dev called once after initial deployment.
/// @param _name the user readable name of the signing domain for EIP712
/// @param _version the current major version of the signing domain for EIP712
function __EIP712MetaTransaction_init(string memory _name, string memory _version)
    internal
    onlyInitializing
{
    name = _name;
    version = _version;

    __EIP712_init(_name, _version);
}
```

> Resolved in [RollaProject/quant-protocol@25112fa](https://github.com/RollaProject/quant-protocol/commit/25112fa93a650f7b889e8472faf75dd5c471cdf2), but upgradeability was later removed as per [RollaProject/quant-protocol#90](https://github.com/RollaProject/quant-protocol/pull/90).

description:
RewardController.handleAction has a special case to handle the case when user is a minipool market:
• RewardsController.sol#L134-L145:
```solidity
if (_isAtokenERC6909[user] == true) {
    (uint256 assetID,) = IAERC6909(user).getIdForUnderlying(IAToken(msg.sender).WRAPPER_ADDRESS());
    // For trancheATokens we calculate the total supply of the AERC6909 ID for the assetID.
    // We subtract the current balance.
    uint256 totalSupplyAsset = IAERC6909(user).scaledTotalSupply(assetID); // <<<
    uint256 diff = totalSupplyAsset - userBalance;
    _totalDiff[msg.sender] = _totalDiff[msg.sender] - lastReportedDiff[msg.sender][user] + diff;
    lastReportedDiff[msg.sender][user] = diff;
    userBalance = totalSupplyAsset;
}
```
We can see that the function fetches scaledTotalSupply in order to compute the difference between the shares of MLP aToken which are due to the minipool and what is actually held by the minipool. These "shares" which are not accounted for in aToken.scaledTotalSupply should be rewarded, and thus this is why _totalDiff[msg.sender] is computed and then added to totalSupply for updating reward state:
• RewardsController.sol#L146-L148:
```solidity
_updateUserRewardsPerAssetInternal(
    msg.sender,
    user,
    userBalance,
    totalSupply + _totalDiff[msg.sender] // <<<
);
```
Unfortunately, it is inaccurate to use IAERC6909(user).scaledTotalSupply in this context, since the total supply is scaled according to the minipool market index, while all other amounts are only scaled according to main lending pool index. To showcase how it can lead to DOS of transfers from the ERC6909 market, we will use a simple example:
Scenario:
• Preconditions:
Params
Value
asset
aWETH
MLP liquidity index
minipool liquidity index
1.05
initial total supply
• Steps:
– Alice mints 100 aWETH by depositing in the main lending pool.
– Alice deposits the 100 aWETH into minipool, and is minted 95.2 shares of aWETH6909. After this step, aWETH6909.scaledTotalSupply is 95.2e18.
• Alice attempts to withdraw the 100 aWETH, but the following values are used in RewardController.handleAction during transfer:
– IncentivizedERC20.sol#L191-L199:
```solidity
if (address(_getIncentivesController()) != address(0)) {
    uint256 currentTotalSupply = _totalSupply;
    _getIncentivesController().handleAction(sender, currentTotalSupply, oldSenderBalance); // <<<
    if (sender != recipient) {
        _getIncentivesController().handleAction(
            recipient, currentTotalSupply, oldRecipientBalance
        );
    }
}
```
Params
Value
sender
aWETH6909
currentTotalSupply
100e18
oldSenderBalance
100e18
Which means handleAction will underflow (scaledTotalSupply == 95.2e18):
– RewardsController.sol#L134-L145:
```solidity
if (_isAtokenERC6909[user] == true) {
    (uint256 assetID,) = IAERC6909(user).getIdForUnderlying(IAToken(msg.sender).WRAPPER_ADDRESS());
    // For trancheATokens we calculate the total supply of the AERC6909 ID for the assetID.
    // We subtract the current balance.
    uint256 totalSupplyAsset = IAERC6909(user).scaledTotalSupply(assetID);
    uint256 diff = totalSupplyAsset - userBalance; // <<<
    _totalDiff[msg.sender] = _totalDiff[msg.sender] - lastReportedDiff[msg.sender][user] + diff;
    lastReportedDiff[msg.sender][user] = diff;
    userBalance = totalSupplyAsset;
}
```
Alice is unable to withdraw her funds.

recommendation:
We should use totalSupply to keep units consistent:
• RewardsController.sol#L134-L145:
```solidity
if (_isAtokenERC6909[user] == true) {
    (uint256 assetID,) = IAERC6909(user).getIdForUnderlying(IAToken(msg.sender).WRAPPER_ADDRESS());
    // For trancheATokens we calculate the total supply of the AERC6909 ID for the assetID.
    // We subtract the current balance.
    uint256 totalSupplyAsset = IAERC6909(user).totalSupply(assetID);
    uint256 diff = totalSupplyAsset - userBalance;
    _totalDiff[msg.sender] = _totalDiff[msg.sender] - lastReportedDiff[msg.sender][user] + diff;
    lastReportedDiff[msg.sender][user] = diff;
    userBalance = totalSupplyAsset;
}
```
Note that it may seem a bit counterintuitive, because this total supply includes shares of lending pool which are accrued as interest, and have never been "minted" yet.

description:
The ERC721Base contract implements the standard ERC721 interfaces. Additionally, it implements the enumerability of all token IDs owned by the user.
In particular, mapping(address => uint256[]) internal _userTokens is designed to record all the token IDs held by the user and mapping(uint256 => uint256) internal _indexOfToken records the index of the token inside the user's token array. Meanwhile, the _addTokenTo() and _removeTokenFrom() routines are designed to manage the token IDs held by the user. While examining the related logic, we observe the current implementation should be improved.
To elaborate, we show below the related code snippet of the ERC721Base contract. Inside the _addTokenTo() routine, the statement of _userTokens[_to].push(_tokenId) (line 407) is executed to push the _tokenId to the _to's token array. Subsequently, the statement of _indexOfToken[_tokenId] = _userTokens[_to].length (line 408) is executed to record the index of the _tokenId inside the user's token array. However, it ignores the fact that the index of the array starts from 0.
```solidity
function _addTokenTo(address _to, uint256 _tokenId) internal {
    _tokenOwner[_tokenId] = _to;
    _userTokens[_to].push(_tokenId);
    _indexOfToken[_tokenId] = _userTokens[_to].length;
    _tokensCount = _tokensCount.add(1);
    _userPurchaseDate[_to] = block.timestamp;
}
```
Moreover, by design, the _removeTokenFrom() routine is used to remove the given _tokenId token from the given _from address. In order to meet the requirement, it needs to replace _tokenId with the last token ID inside the _from's token array and update the index of the last token ID. Eventually, the array's last element should be released via pop(). However, it comes to our attention that the current implementation is far from the design.
```solidity
function _removeTokenFrom(address _from, uint256 _tokenId) internal {
    uint256 tokenIndex = _indexOfToken[_tokenId];
    uint256 lastTokenIndex = _userTokens[_from].length.sub(1);
    uint256 lastTokenId = _indexOfToken[lastTokenIndex];
    _userTokens[_from][tokenIndex] = lastTokenId;
    _indexOfToken[lastTokenId] = tokenIndex;
    _userTokens[_from].pop();
    _tokenOwner[_tokenId] = address(0);
    _tokensCount = _tokensCount.sub(1);
    if (_userTokens[_from].length == 0) {
        delete _userTokens[_from];
    }
}
```

recommendation:
Correct the implementation of above-mentioned routines as below:
```solidity
function _addTokenTo(address _to, uint256 _tokenId) internal {
    _tokenOwner[_tokenId] = _to;
    _userTokens[_to].push(_tokenId);
    _indexOfToken[_tokenId] = _userTokens[_to].length - 1;
    _tokensCount = _tokensCount.add(1);
    _userPurchaseDate[_to] = block.timestamp;
}

function _removeTokenFrom(address _from, uint256 _tokenId) internal {
    uint256 tokenIndex = _indexOfToken[_tokenId];
    uint256 lastTokenId = _userTokens[_from][_userTokens[_from].length - 1];
    _userTokens[_from][tokenIndex] = lastTokenId;
    delete _indexOfToken[_tokenId];
    _userTokens[_from].pop();
    _tokenOwner[_tokenId] = address(0);
    _tokensCount = _tokensCount.sub(1);
    if (_userTokens[_from].length == 0) {
        delete _userTokens[_from];
    }
}
```

description:
The issue arises when users attempt to use the flashLoanSimple function:
```solidity
function flashLoanSimple(
    IFlashLoanReceiver receiver,
    uint256 amount,
    bytes calldata params
) external nonReentrant {
    uint256 available = availableBorrowable();
    if (amount > available || amount > maxLoan) revert AmountTooHigh(amount);
    uint256 fee = exemptionList[msg.sender] ? 0 : amount.bp(fees.flash);
    uint256 toRepay = amount + fee;
    uint256 balanceBefore = asset.balanceOf(address(this));
    totalLent += amount;
    asset.safeTransferFrom(address(this), address(receiver), amount);
    receiver.executeOperation(address(asset), amount, fee, msg.sender, params);
    if ((asset.balanceOf(address(this)) - balanceBefore) < toRepay)
        revert FlashLoanDefault(msg.sender, amount);
    emit FlashLoan(msg.sender, amount, fee);
}
```
To transfer the fund to users, it uses asset.safeTransferFrom(address(this), address(receiver), amount); This line intends to transfer funds to the user. However, it fails because safeTransferFrom requires the contract to have a sufficient allowance to "spend" on behalf of itself. In the context of ERC20 tokens like USDC, the transferFrom function includes a crucial check: value <= allowed[from][msg.sender]. However, because the contract has not yet approved itself, leading to a situation where the allowance remains at zero, and hence the transferFrom call reverts.
```solidity
function transferFrom(
    address from,
    address to,
    uint256 value
) external override whenNotPaused notBlacklisted(msg.sender) notBlacklisted(from) notBlacklisted(to) returns (bool) {
    require(
        value <= allowed[from][msg.sender],
        "ERC20: transfer amount exceeds allowance"
    );
    _transfer(from, to, value);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(value);
    return true;
}
```
USDC - FiatTokenV1.sol: https://arbiscan.io/address/0xaf88d065e77c8cc2239327c5edb3a432268e5831 Using transfer does not require additional approval.

recommendation:
Replacing the safeTransferFrom function with safeTransfer:
```solidity
function flashLoanSimple(
    IFlashLoanReceiver receiver,
    uint256 amount,
    bytes calldata params
) external nonReentrant {
    uint256 available = availableBorrowable();
    if (amount > available || amount > maxLoan) revert AmountTooHigh(amount);
    uint256 fee = exemptionList[msg.sender] ? 0 : amount.bp(fees.flash);
    uint256 toRepay = amount + fee;
    uint256 balanceBefore = asset.balanceOf(address(this));
    totalLent += amount;
    asset.safeTransfer(address(receiver), amount);
    receiver.executeOperation(address(asset), amount, fee, msg.sender, params);
    if ((asset.balanceOf(address(this)) - balanceBefore) < toRepay)
        revert FlashLoanDefault(msg.sender, amount);
    emit FlashLoan(msg.sender, amount, fee);
}
```

description:
An incorrect time check causes ve_supply[t] to be updated incorrectly. When RewardsDistributorV2#checkpoint_total_supply() is called, the total supply at time t will be stored in ve_supply[t] for future distribution reward calculations:
```solidity
function _checkpoint_total_supply() internal {
    address ve = voting_escrow;
    uint t = time_cursor;
    uint rounded_timestamp = block.timestamp / WEEK * WEEK;
    IVotingEscrow(ve).checkpoint();
    for (uint i = 0; i < 20; i++) {
        if (t > rounded_timestamp) {
            break;
        } else {
            uint epoch = _find_timestamp_epoch(ve, t);
            IVotingEscrow.Point memory pt = IVotingEscrow(ve).point_history(epoch);
            int128 dt = 0;
            if (t > pt.ts) {
                dt = int128(int256(t - pt.ts));
            }
            ve_supply[t] = Math.max(uint(int256(pt.bias - pt.slope * dt)), 0);
        }
        t += WEEK;
    }
    time_cursor = t;
}
```
ve_supply[t] should be only updated when t week has end (t + 1 weeks <= block.timestamp). However, ve_supply[t] could be updated incorrectly when block.timestamp % 1 weeks is 0. If a veNFT is created immediately after checkpoint_total_supply() is called, its balance will not be accounted for in ve_supply[t]. A malicious user could exploit this flaw to steal future distribution rewards.
Copy below codes to RewardsDistributorV2.t.sol and run forge test --match-test testStealFutureDistributeReward
```solidity
function testStealFutureDistributeReward() public {
    initializeVotingEscrow();
    vm.warp((block.timestamp + 1 weeks) / 1 weeks * 1 weeks);
    minter.update_period();
    // distribution reward
    flowDaiPair.approve(address(escrow), 2e18);
    escrow.create_lock(2e18,50 weeks);
    DAI.transfer(address(distributor), 10e18);
    vm.warp(block.timestamp + 1 weeks);
    // tokens_per_week
    minter.update_period();
    // distribution reward
    assertApproxEqAbs(distributor.claimable(3), 10e18, 0.2e18);
    distributor.claim(3);
    assertLt(DAI.balanceOf(address(distributor)), 0.2e18);
    assertEq(distributor.claimable(1), 5e18);
    vm.expectRevert();
    distributor.claim(1);
}
```
A malicious user could create a new veNFT to steal future distribution rewards, leaving other eligible users without any rewards to claim.

recommendation:
Make sure that ve_supply[t] should be only updated when t week has end (t + 1 weeks <= block.timestamp):
```solidity
function _checkpoint_total_supply() internal {
    address ve = voting_escrow;
    uint t = time_cursor;
    uint rounded_timestamp = block.timestamp / WEEK * WEEK;
    IVotingEscrow(ve).checkpoint();
    for (uint i = 0; i < 20; i++) {
        if (t >= rounded_timestamp) {
            break;
        } else {
            uint epoch = _find_timestamp_epoch(ve, t);
            IVotingEscrow.Point memory pt = IVotingEscrow(ve).point_history(epoch);
            int128 dt = 0;
            if (t > pt.ts) {
                dt = int128(int256(t - pt.ts));
            }
            ve_supply[t] = Math.max(uint(int256(pt.bias - pt.slope * dt)), 0);
        }
        t += WEEK;
    }
    time_cursor = t;
}
```

description:
The reward formula in Reward Distributors (RewardsDistributor.sol and RewardsDistributor6909.sol) uses an index to track accrual of rewards per unit of aToken held. The size for the index is set to be uint104, and it should be well enough for cases when assetTotalSupply >= 10**assetDecimals or decimals is a low value. However in the case totalSupply is dust, even for a short amount of time, the index can reach type(uint104).max, and no further reward accrual can happen:
• RewardsDistributor.sol#L279:
```solidity
if (newIndex != oldIndex) {
    require(newIndex <= type(uint104).max, "Index overflow"); // <<<
    //optimization: storing one after another saves one SSTORE
    rewardConfig.index = uint104(newIndex);
    rewardConfig.lastUpdateTimestamp = uint32(block.timestamp);
    emit AssetIndexUpdated(asset, reward, newIndex);
} else {
    rewardConfig.lastUpdateTimestamp = uint32(block.timestamp);
}
```
The formula for computing the index is given below:
• RewardsDistributor.sol#L501:
```solidity
uint256 currentTimestamp = block.timestamp > distributionEnd ? distributionEnd : block.timestamp;
uint256 timeDelta = currentTimestamp - lastUpdateTimestamp;
return (emissionPerSecond * timeDelta * (10 ** decimals)) / totalBalance + currentIndex;
```
emissionPerSecond is the number of reward tokens to emit globally per second. decimals is the decimals precision for asset token considered. totalBalance is the total supply of the asset token considered.
Scenario:
• Preconditions:
Parameter
Value
Asset token
aWeth (decimals: 18)
Reward token
DAI (decimals: 18)
Total reward amount (A)
1000 DAI
Total asset supply
Time elapsed (t)
12 sec (~1 block)
Distribution duration (T)
1 month
Very reasonable values except for total asset supply which may need some stars to align.
• Index calculation: First let's calculate emissionPerSecond denoted r:
r = A/T = (1000 * 10**18)/262800 = 3.8 * 10**14 Which yields the index value:
i = r*t*10**d = (3.8 * 10**14) * 12 * 10**18 = 4.56 * 10**34 > 2**104

recommendation:
Multiple recommendations can be considered:
• Increasing index size: When A = 1_000_000e18 and d = 18, index would be safe from reverting using uint140.
• Do not accrue index when normalized total supply is below a threshold (which should not happen anyway in any reasonable case):
```solidity
if (
    emissionPerSecond == 0 ||
    totalBalance == 0 ||
    (decimals == 18 && totalBalance <= UPDATE_THRESHOLD) || // @audit ok to be below threshold for low decimal tokens
    lastUpdateTimestamp == block.timestamp ||
    lastUpdateTimestamp >= distributionEnd
) {
    return currentIndex;
}
```
Additionally to avoid reverting at any costs during action handling, overflow could be allowed so the index would naturally wrap around (it would be safe since we only use index differences when computing rewards).

description:
In LibMuon, all signatures do not distinguish between type prefixes, and abi.encodePacked is used when calculating the hash. Cause when abi.encodePacked, if there is a dynamic array, different structures but the same hash value may be obtained. Due to conflicting hash values, signatures can be substituted for each other, making malicious use of illegal signatures possible.
The following two methods are examples:
1. verifyPrices:
```solidity
function verifyPrices(PriceSig memory priceSig, address partyA) internal view {
    MuonStorage.Layout storage muonLayout = MuonStorage.layout();
    require(priceSig.prices.length == priceSig.symbolIds.length, "LibMuon: Invalid length");
    bytes32 hash = keccak256(
        abi.encodePacked(
            muonLayout.muonAppId,
            priceSig.reqId,
            address(this),
            partyA,
            priceSig.upnl,
            priceSig.totalUnrealizedLoss,
            priceSig.symbolIds,
            priceSig.prices,
            priceSig.timestamp,
            getChainId()
        )
    );
    verifyTSSAndGateway(hash, priceSig.sigs, priceSig.gatewaySignature);
}
```
2. verifyPartyAUpnlAndPrice
```solidity
function verifyPartyAUpnlAndPrice(
    SingleUpnlAndPriceSig memory upnlSig,
    address partyA,
    uint256 symbolId
) internal view {
    MuonStorage.Layout storage muonLayout = MuonStorage.layout();
    require(
        block.timestamp <= upnlSig.timestamp + muonLayout.upnlValidTime,
        "LibMuon: Expired signature"
    );
    bytes32 hash = keccak256(
        abi.encodePacked(
            muonLayout.muonAppId,
            upnlSig.reqId,
            address(this),
            partyA,
            AccountStorage.layout().partyANonces[partyA],
            upnlSig.upnl,
            symbolId,
            upnlSig.price,
            upnlSig.timestamp,
            getChainId()
        )
    );
    verifyTSSAndGateway(hash, upnlSig.sigs, upnlSig.gatewaySignature);
}
```
We exclude the same common part (muonAppId/reqId/address(this)/timestamp/getChainId()).
Through the following simplified test code, although the structure is different, the hash value is the same at that time:
```solidity
function test() external {
    address verifyPrices_partyA = address(0x1);
    int256 verifyPrices_upnl = 100;
    int256 verifyPrices_totalUnrealizedLoss = 100;
    uint256[] memory verifyPrices_symbolIds = new uint256[](1);
    verifyPrices_symbolIds[0] = 1;
    uint256[] memory verifyPrices_prices = new uint256[](1);
    verifyPrices_prices[0] = 1000;
    bytes32 verifyPrices = keccak256(abi.encodePacked(
        verifyPrices_partyA,
        verifyPrices_upnl,
        verifyPrices_totalUnrealizedLoss,
        verifyPrices_symbolIds,
        verifyPrices_prices
    ));
    address verifyPartyAUpnlAndPrice_partyA = verifyPrices_partyA;
    int256 verifyPartyAUpnlAndPrice_partyANonces = verifyPrices_upnl;
    int256 verifyPartyAUpnlAndPrice_upnl = verifyPrices_totalUnrealizedLoss;
    uint256 verifyPartyAUpnlAndPrice_symbolId = verifyPrices_symbolIds[0];
    uint256 verifyPartyAUpnlAndPrice_price = verifyPrices_prices[0];
    bytes32 verifyPartyAUpnlAndPrice = keccak256(abi.encodePacked(
        verifyPartyAUpnlAndPrice_partyA,
        verifyPartyAUpnlAndPrice_partyANonces,
        verifyPartyAUpnlAndPrice_upnl,
        verifyPartyAUpnlAndPrice_symbolId,
        verifyPartyAUpnlAndPrice_price
    ));
    console.log("verifyPrices == verifyPartyAUpnlAndPrice:", verifyPrices == verifyPartyAUpnlAndPrice);
}
```
$ forge test -vvv
Running 1 test for test/Counter.t.sol:CounterTest
[PASS] test() (gas: 4991)
Logs:
verifyPrices == verifyPartyAUpnlAndPrice: true
Test result: ok. 1 passed; 0 failed; finished in 11.27ms
From the above test example, we can see that the verifyPrices and verifyPartyAUpnlAndPrice signatures can be used interchangeably. If we get a legal verifyPartyAUpnlAndPrice, it can be used as the signature of verifyPrices(). Use partyANonces as upnl, etc.
Signatures can be reused due to hash collisions, through illegal signatures, using illegal unpl, etc.

recommendation:
It is recommended to add the prefix of the hash, or use api.encode. Such as:
```solidity
function verifyPrices(PriceSig memory priceSig, address partyA) internal view {
    MuonStorage.Layout storage muonLayout = MuonStorage.layout();
    require(priceSig.prices.length == priceSig.symbolIds.length, "LibMuon: Invalid length");
    bytes32 hash = keccak256(
        abi.encodePacked(
            "verifyPrices",
            muonLayout.muonAppId,
            priceSig.reqId,
            address(this),
            partyA,
            priceSig.upnl,
            priceSig.totalUnrealizedLoss,
            priceSig.symbolIds,
            priceSig.prices,
            priceSig.timestamp,
            getChainId()
        )
    );
    verifyTSSAndGateway(hash, priceSig.sigs, priceSig.gatewaySignature);
}
```

description:
```solidity
Anyone can call KeeperFactory#request, inputting empty arrays as parameters, and
the call will succeed, and the caller receives a fee.
Attacker can perform this attack many times within a loop to steal ALL keeper fees
from protocol.
Expected Workflow:
• User calls Market#update to open a new position
• Market calls Oracle#request to request a new oracleVersion
– The User's account gets added to a callback array of the market
• Once new oracleVersion gets committed, keepers can call
KeeperFactory#settle, which will call Market#update on accounts in the
Market's callback array, and pay the keeper(i.e. caller) a fee.
– KeeperFactory#settle call will fail if there is no account to settle(i.e. if
callback array is empty)
– After settleing an account, it gets removed from the callback array
The issue:
Here is KeeperFactory#settle function:
function settle(bytes32[] memory ids, IMarket[] memory markets, uint256[] memory
versions, uint256[] memory maxCounts)
external
keep(settleKeepConfig(), msg.data, 0, "")
{
    if (
        ids.length != markets.length ||
        ids.length != versions.length ||
        ids.length != maxCounts.length ||
        // Prevent calldata stuffing
        abi.encodeCall(KeeperFactory.settle, (ids, markets, versions,
        maxCounts)).length != msg.data.length
    )
        revert KeeperFactoryInvalidSettleError();
    for (uint256 i; i < ids.length; i++)
        IKeeperOracle(address(oracles[ids[i]])).settle(markets[i], versions[i],
        maxCounts[i]);
}
```
As we can see, function does not check if the length of the array is 0, so if user
inputs empty array, the for loop will not be entered, but the keeper still receives a
fee via the keep modifier.
Attacker can have a contract perform the attack multiple times in a loop to drain all
fees:
```solidity
interface IKeeperFactory{
    function settle(bytes32[] memory ids,IMarket[] memory markets,uint256[]
    memory versions,uint256[] memory maxCounts
    ) external;
}
interface IMarket{
    function update()external;
}
contract AttackContract{
    address public attacker;
    address public keeperFactory;
    IERC20 public keeperToken;
    constructor(address perennialDeployedKeeperFactory, IERC20 _keeperToken){
        attacker=msg.sender;
        keeperFactory=perennialDeployedKeeperFactory;
        keeperToken=_keeperToken;
    }
    function attack()external{
        require(msg.sender==attacker,"not allowed");
        bool canSteal=true;
        // empty arrays as parameters
        bytes32[] memory ids=[];
        IMarket[] memory markets=[];
        uint256[] memory versions=[];
        uint256[] memory maxCounts=[];
        // perform attack in a loop till all funds are drained or call reverts
        while(canSteal){
            try
            IKeeperFactory(keeperFactory).settle(ids,markets,versions,maxCounts){
            //
            }catch{
                canSteal=false;
            }
        }
        keeperToken.transfer(msg.sender, keeperToken.balanceOf(address(this)));
    }
}
```
All keeper fees can be stolen from protocol, and there will be no way to incentivize
Keepers to commitRequested oracle version, and other keeper tasks

recommendation:
```solidity
Within KeeperFactory#settle function, revert if ids.length==0:
function settle(
    bytes32[] memory ids,
    IMarket[] memory markets,
    uint256[] memory versions,
    uint256[] memory maxCounts
)external keep(settleKeepConfig(), msg.data, 0, "") {
    if (
        ids.length==0 ||
        ids.length != markets.length ||
        ids.length != versions.length ||
        ids.length != maxCounts.length ||
        // Prevent calldata stuffing
        abi.encodeCall(KeeperFactory.settle, (ids, markets, versions,
        maxCounts)).length != msg.data.length
    ) revert KeeperFactoryInvalidSettleError();
    for (uint256 i; i < ids.length; i++)
        IKeeperOracle(address(oracles[ids[i]])).settle(markets[i], versions[i],
        maxCounts[i]);
}
```

description:
Lister unfairly double pays the tax used while he is cancelling his listing through Listings::cancelListings().
When a user is creating his listing through Listings::createListings(), he is paying upfront the tax that is expected to be used for the whole duration of the listing.
However, if he decides to cancel the listing after some time calling Listings::cancelListings(), he will find himself paying again the portion of the tax that has been used until this point. Let's see the Listings::cancelListings():
```solidity
function cancelListings(address _collection, uint[] memory _tokenIds, bool _payTaxWithEscrow) public lockerNotPaused {
    uint fees;
    uint refund;
    for (uint i; i < _tokenIds.length; ++i) {
        uint _tokenId = _tokenIds[i];
        // Read the listing in a single read
        Listing memory listing = _listings[_collection][_tokenId];
        // Ensure the caller is the owner of the listing
        if (listing.owner != msg.sender) revert CallerIsNotOwner(listing.owner);
        // We cannot allow a dutch listing to be cancelled. This will also check that a liquid listing has not
        // expired, as it will instantly change to a dutch listing type.
        Enums.ListingType listingType = getListingType(listing);
        if (listingType != Enums.ListingType.LIQUID) revert CannotCancelListingType();
        // Find the amount of prepaid tax from current timestamp to prepaid timestamp
        // and refund unused gas to the user.
        (uint _fees, uint _refund) = _resolveListingTax(listing, _collection, false);
        emit ListingFeeCaptured(_collection, _tokenId, _fees);
        fees += _fees;
        refund += _refund;
        // Delete the listing objects
        delete _listings[_collection][_tokenId];
        // Transfer the listing ERC721 back to the user
        locker.withdrawToken(_collection, _tokenId, msg.sender);
    }
    // cache
    ICollectionToken collectionToken = locker.collectionToken(_collection);
    // Burn the ERC20 token that would have been given to the user when it was initially created
    uint requiredAmount = ((1 ether * _tokenIds.length) * 10 ** collectionToken.denomination()) - refund;
    payTaxWithEscrow(address(collectionToken), requiredAmount, _payTaxWithEscrow);
    collectionToken.burn(requiredAmount + refund);
}
```
Link to code
As we can see, user is expected to return back the whole 1e18-refund. It helps to remember that when he created the listing he “took” 1e18-TAX where, now, TAX=refund+fees. So the user is expected to give back to the protocol 1e18-refund while he got 1e18-refund-fees. The difference of what he got at the start and what he is expected to return now:
whatHeGot - whatHeMustReturn = (1e18 - refund - fees) - (1e18 - refund) = -fees
So, now the user has to get out of his pocket and pay again for the fees while, technically, he has paid for them in the start by not ever taking them.
Furthermore, in this way, as we can see from this line, the protocol burns the whole 1e18 without considering the tax that got actually used and shouldn't be burned as it will be deposited to the UniswapV4Implementation:
```solidity
collectionToken.burn(requiredAmount + refund);
```
Internal pre-conditions
1. User creates a listing from Listings::createListings().
External pre-conditions
1. User wants to cancel his listing by Listings::cancelListings().
Attack Path
1. User creates a listing from Listings::createListings() and takes back as collectionTokens -> 1e18-prepaidTax.
2. Some time passes by.
3. User wants to cancel the listing by calling Listings::cancelListings() and he has to give back 1e18-unusedTax. This mean that he has to give also the usedTax amount.
The impact of this serious vulnerability is that the user is forced to double pay the tax that has been used for the duration that his listing was up. He, firstly, paid for it by not taking it and now, when he cancels the listing, he has to pay it again out of his own pocket. This results to unfair loss of funds for whoever tries to cancel his listing.

recommendation:
To mitigate this vulnerability successfully, consider not requiring user to return the fee variable as well:
```solidity
function cancelListings(address _collection, uint[] memory _tokenIds, bool _payTaxWithEscrow) public lockerNotPaused {
    uint fees;
    uint refund;
    for (uint i; i < _tokenIds.length; ++i) {
    }
    // cache
    ICollectionToken collectionToken = locker.collectionToken(_collection);
    // Burn the ERC20 token that would have been given to the user when it was initially created
    uint requiredAmount = ((1 ether * _tokenIds.length) * 10 ** collectionToken.denomination()) - refund - fees;
    payTaxWithEscrow(address(collectionToken), requiredAmount, _payTaxWithEscrow);
    collectionToken.burn(requiredAmount + refund);
}
```

description:
Users get undercharged when topping up membership due to faulty calculation of
the cover cost.
When a user is topping up their membership, a prorated cost for the additional
cover is calculated based on the remaining days.
This is done in the function FairSideNetwork.sol::calculateCoverCost
```solidity
/**
 * @return cover cost (uint)
 */
function calculateCoverCost(uint256 costShareBenefit, uint256 duration) internal
view returns (uint256) {
    uint256 coverCost = getCoverCost();
    uint256 fee = costShareBenefit.mul(coverCost);
    if (block.timestamp > duration) {
        return fee;
    } else {
        uint256 dailycost = coverCost / MEMBERSHIP_DURATION;
        uint256 daysRemaining = (duration - block.timestamp) / 86400;
        if (daysRemaining == 0) {
            return fee;
        }
        uint256 rate = daysRemaining * dailycost;
        uint256 proratedCostETH = costShareBenefit.mul(rate);
        return (proratedCostETH);
    }
}
```
The problem is that dailycost is calculated in seconds while daysRemaining is
calculated in days.
This discrepancy results in the rate being much lower and the user is undercharged
when topping up membership.
• Let's take a user who purchases 50 ETH of protection. They will get charged
0.0195 * 50e18 = 975000000000000000 for a full year
• If halfway through the year, they want to top up another 50 ETH, they should
be charged approximately half what it would cost for 1 year
• Instead, due to the faulty calculation, they will be charged much less as can be
seen in the POC below:
```solidity
import { assert, expect } from "chai";
import { ethers } from "hardhat";
import { ethToWei, weiToEth, toUnits, toWholeUnits, increaseTime,
createRandomWalletAddress, getEthBalance } from "../helpers/base";
import { SignerWithAddress } from "@nomiclabs/hardhat-ethers/signers";
import { FSD, FairSideNetwork } from "../../typechain-types";
import { FSDPhase } from "../Interfaces/enums";
import fsdContractsDeployer from "../helpers/test.deployer";

describe("FaultyTopup", () => {
    // Accounts
    let owner: SignerWithAddress;
    let random: SignerWithAddress;
    let userAccount3: SignerWithAddress;
    let userAccount1: SignerWithAddress;
    let fsd: FSD;
    let coverID: number;
    let fairSideNetwork: FairSideNetwork;
    let timelockAccount: SignerWithAddress;
    let accounts: any[];
    const coverAddress = "0x41427a1488a16a150959347d05c33e54d4d8467e";

    // purchase membership
    before(async () => {
        accounts = await ethers.getSigners();
        [owner, random, userAccount3, userAccount1] = await ethers.getSigners();
        ({ fsd, fairSideNetwork, timelockAccount } = await
        fsdContractsDeployer(owner));
        const balance = await ethers.provider.getBalance(fsd.address);
    });

    it("should purchase PWP membership cover with ETH ", async () => {
        const [joe, tom] = accounts.slice(17, 19);
        // add funds to capital pool by bonding FSD to curve
        await fsd.connect(joe).bond(1, {
            value: ethToWei("10000"),
        });
        // purchase pwp cover
        const cost = (await
        fairSideNetwork.connect(tom).estimateCost(ethToWei("50"), 0)) as any;
        console.log("50 ETH for 365 days:", cost);
        await fairSideNetwork.connect(tom).purchaseMembership(ethToWei("50"),
        coverAddress, { value: ethToWei("1.5") });

        let coverId = 1;
        let membership = await fairSideNetwork.getMembership(coverId);
        // Increase wait time by half a year.
        await increaseTime(182.5 * 86400);
        const proratedCost = (await
        fairSideNetwork.connect(tom).estimateCost(ethToWei("50"),
        membership.duration)) as any;

        console.log("50 ETH for 182.5 days:", proratedCost);
        await expect(fairSideNetwork.connect(tom).topupMembership(coverId,
        ethToWei("50"), { value: ethToWei("1.5") })).not.be.reverted;
    });
});
```
• Place the POC in a file called faultyTopup.test.ts in the test/network folder
and run it:
npx hardhat test ./test/network/faultyTopup.test.ts
FaultyTopup
50 ETH for 365 days: BigNumber { value: "975000000000000000" }
50 ETH for 182.5 days: BigNumber { value: "5626902581300" }
Now if we fix the issue by modifying the calculation in
FairSideNetwork.sol::calculateCoverCost
```solidity
function calculateCoverCost(uint256 costShareBenefit, uint256 duration)
internal view returns (uint256) {
    uint256 coverCost = getCoverCost();
    uint256 fee = costShareBenefit.mul(coverCost);
    if (block.timestamp > duration) {
        return fee;
    } else {
        uint256 dailycost = (coverCost * 86400) / MEMBERSHIP_DURATION;
        uint256 daysRemaining = (duration - block.timestamp) / 86400;
        if (daysRemaining == 0) {
            return fee;
        }
        uint256 rate = daysRemaining * dailycost;
        uint256 proratedCostETH = costShareBenefit.mul(rate);
        return (proratedCostETH);
    }
}
```
Then rerun the POC, we get:
50 ETH for 365 days: BigNumber { value: "975000000000000000" }
50 ETH for 182.5 days: BigNumber { value: "486164383561638600" }
This is now accurate and 50 ETH for half a year is approximately half what it would
be for 1 year.
Loss of funds for the protocol and other users/stakers as premium top ups are
undercharged.

recommendation:
Fix the issue by modifying the calculation in
FairSideNetwork.sol::calculateCoverCost
```solidity
function calculateCoverCost(uint256 costShareBenefit, uint256 duration)
internal view returns (uint256) {
    uint256 coverCost = getCoverCost();
    uint256 fee = costShareBenefit.mul(coverCost);
    if (block.timestamp > duration) {
        return fee;
    } else {
        uint256 dailycost = (coverCost * 86400) / MEMBERSHIP_DURATION;
        uint256 daysRemaining = (duration - block.timestamp) / 86400;
        if (daysRemaining == 0) {
            return fee;
        }
        uint256 rate = daysRemaining * dailycost;
        uint256 proratedCostETH = costShareBenefit.mul(rate);
        return (proratedCostETH);
    }
}
```

description:
In the init_ONft instruction, the token_mint is set without validation, allowing the initialization of a token_mint with a freeze_authority. SPL tokens with a freeze authority can have their accounts frozen by the token issuer or an authorized entity, posing a risk to the functioning of the ONFT.

```solidity
impl InitAdapterONft<_> {
    pub fn apply(ctx: &mut Context<InitAdapterONft>, params: &InitAdapterONftParams) -> Result<()> {
        ctx.accounts.ONft_config.bump = ctx.bumps.ONft_config;
        ctx.accounts.ONft_config.token_mint = ctx.accounts.token_mint.key();
        ctx.accounts.ONft_config.ext = ONftConfigExt::Adapter(ctx.accounts.token_escrow.key());
        ctx.accounts.ONft_config.token_program = ctx.accounts.token_program.key();
        ctx.accounts.lz_receive_types_accounts.ONft_config = ctx.accounts.ONft_config.key();
        ctx.accounts.lz_receive_types_accounts.token_mint = ctx.accounts.token_mint.key();
        let oapp_signer = ctx.accounts.ONft_config.key();
        ctx.accounts.ONft_config.init(
            params.endpoint_program,
            params.admin,
            params.shared_decimals,
            ctx.accounts.token_mint.decimals,
            ctx.remaining_accounts,
            oapp_signer,
        )
    }
}
```

If the token_escrow is frozen, it will be impossible to transfer the locked token to it, causing a Denial of Service (DoS) in the send instruction. This will render the ONFT unusable because token transfers to the token_escrow will revert at this point:

```solidity
match &ctx.accounts.ONft_config.ext {
    ONftConfigExt::Adapter(_) => {
        if let Some(escrow_acc) = &mut ctx.accounts.token_escrow {
            // lock
            token_interface::transfer_checked(
                CpiContext::new(
                    ctx.accounts.token_program.to_account_info(),
                    TransferChecked {
                        from: ctx.accounts.token_source.to_account_info(),
                        mint: ctx.accounts.token_mint.to_account_info(),
                        to: escrow_acc.to_account_info(),
                        authority: ctx.accounts.signer.to_account_info(),
                    },
                ),
                amount_sent_ld,
                ctx.accounts.token_mint.decimals,
            )?;
        } else {
            return Err(ONftError::InvalidTokenEscrow.into());
        }
    }
}
```

recommendation:
1. During ONFT initialization, check if the token_mint has a freeze_authority and return an error if detected.
2. If support for such tokens is necessary, display a warning on the UI to inform traders of the associated risks.
3. Keep in mind that major regulated stablecoins, such as USDC, have a freeze_authority for security reasons (e.g., preventing money laundering). If the protocol wishes to support USDC or similar tokens, implement an allowlist for trusted tokens while applying strict checks on others.
Add this check in the init_ONFT function to the mint account to prevent using tokens with freeze authority:
```solidity
if mint_account.freeze_authority.is_some() {
    return Err(Error::MintHasFreezeAuthority);
}
```

description:
During the liquidation process, all assets in a MarginAccount are converted to the baseToken (USDC), and debts in each LiquidityPool are cleared with the help of the _clearDebtsWithPools function in MarginAccount. If sufficient funds are available (MarginAccount#L294-L296), modularSwapRouter.swapOutput is used to convert USDC to the exact amount of poolToken needed to repay the liquidity pool:
File: MarginAccount.sol
```solidity
function liquidate(
    uint marginAccountID,
    address baseToken,
    address marginAccountOwner
) external onlyRole(MARGIN_TRADING_ROLE) {
    uint amountOutInUSDC = modularSwapRouter.liquidate(erc20Params, erc721Params);
    erc20ByContract[marginAccountID][baseToken] += amountOutInUSDC;
    _clearDebtsWithPools(marginAccountID, baseToken);
}
```
File: MarginAccount.sol
```solidity
function _clearDebtsWithPools(uint marginAccountID, address baseToken) private {
    // ...
    else {
        uint amountIn = modularSwapRouter.swapOutput(baseToken, availableTokenToLiquidityPool[i], poolDebt);
        erc20ByContract[marginAccountID][baseToken] -= amountIn;
    }
    ILiquidityPool(liquidityPoolAddress).repay(marginAccountID, poolDebt);
}
```
In UniswapModule, the swapOutput function prepares parameters for the swap and executes swapRouter.exactOutput. However, the parameter amountInMaximum is always set to zero. According to Uniswap's documentation, amountInMaximum should be the maximum amount of USDC that can be used to swap for the required asset. Since it's always zero, the swap will revert, failing to convert USDC into the needed poolToken:
File: UniswapModule.sol
```solidity
function swapOutput(uint amountOut) external onlyRole(MODULAR_SWAP_ROUTER_ROLE) returns(uint amountIn) {
    amountIn = getOutputPositionValue(amountOut);
    IERC20(tokenInContract).transferFrom(marginAccount, address(this), amountIn);
    swapRouter.exactOutput(params);
    IERC20(tokenOutContract).transfer(marginAccount, amountOut);
}
```
File: UniswapModule.sol
```solidity
function _preparationOutputParams(uint256 amount) private view returns(ISwapRouter.ExactOutputParams memory params) {
    params = ISwapRouter.ExactOutputParams({
        path: uniswapPath,
        recipient: address(this),
        deadline: block.timestamp,
        amountOut: amount,
        amountInMaximum: 0
    });
}
```
This misconfiguration can cause the swap to fail, potentially leaving the system unable to clear debts during liquidations.

recommendation:
It is advisable to adjust the amountInMaximum in the UniswapModule::swapOutput function to reflect the actual maximum input expected for the swap. This adjustment ensures that the swap does not revert due to an insufficient input amount:
```solidity
function swapOutput(uint amountOut) external onlyRole(MODULAR_SWAP_ROUTER_ROLE) returns(uint amountIn) {
    ISwapRouter.ExactOutputParams memory params = _preparationOutputParams(amountOut);
    amountIn = getOutputPositionValue(amountOut);
    params.amountInMaximum = amountIn;
    IERC20(tokenInContract).transferFrom(marginAccount, address(this), amountIn);
    swapRouter.exactOutput(params);
    IERC20(tokenOutContract).transfer(marginAccount, amountOut);
}
```

Transfer tokens to the router via `safeTransferFrom()`:
```solidity
        function addLiquidity(uint256 amount, uint256 minOutput, uint256 poolId) external returns (uint256) {
            UlyssesPool ulysses = getUlyssesLP(poolId);
            address(ulysses.asset()).safeTransferFrom(msg.sender, address(this), amount);

            amount = ulysses.deposit(amount, msg.sender);

            if (amount < minOutput) revert OutputTooLow();
            return amount;
        }
```

**Proof of Concept:**
```solidity
The router calls the deposit with `msg.sender` as a receiver of shares:
```solidity
        function addLiquidity(uint256 amount, uint256 minOutput, uint256 poolId) external returns (uint256) {
            UlyssesPool ulysses = getUlyssesLP(poolId);

            amount = ulysses.deposit(amount, msg.sender);

            if (amount < minOutput) revert OutputTooLow();
            return amount;
        }
```
And in deposit pool transfer tokens from `msg.sender`, which is the router:
```solidity
