    uint256 index_,
    uint256 npLimitIndex_
) external override nonReentrant {
    PoolState memory poolState = _accruePoolInterest();
    // kick auctions
    KickResult memory result = KickerActions.kickWithDeposit(
        auctions,
        deposits,
        buckets,
        loans,
        poolState,
        index_,
        npLimitIndex_
    );
```
