```

description:
```solidity
`VeryFastRouter::swap` relies on the internal functions [`VeryFastRouter::_findMaxFillableAmtForSell`](https://github.com/sudoswap/lssvm2/blob/78d38753b2042d7813132f26e5573c6699b605ef/src/VeryFastRouter.sol#L556) and [`VeryFastRouter::_findMaxFillableAmtForBuy`](https://github.com/sudoswap/lssvm2/blob/78d38753b2042d7813132f26e5573c6699b605ef/src/VeryFastRouter.sol#L503) to find the maximum possible amount of tokens to be swapped via binary search as below:

VeryFastRouter.sol
576:         // Perform binary search
577:         while (start <= end) {
578:             // We check the price to sell index + 1
579:             (
580:                 CurveErrorCodes.Error error,
581:                 /* newSpotPrice */
582:                 ,
583:                 /* newDelta */
584:                 ,
585:                 uint256 currentOutput,
586:                 /* tradeFee */
587:                 ,
588:                 /* protocolFee */
589:             ) = pair.bondingCurve().getSellInfo(
590:                 spotPrice,
591:                 // get delta from deltaAndFeeMultiplier
592:                 uint128(deltaAndFeeMultiplier >> 96),
593:                 (start + end) / 2,
594:                 // get feeMultiplier from deltaAndFeeMultiplier
595:                 uint96(deltaAndFeeMultiplier),
596:                 protocolFeeMultiplier
597:             );
598:             currentOutput -= currentOutput * royaltyAmount / BASE;//@audit-info assumes royalty amount is linear
599:             // If the bonding curve has a math error, or
600:             // if the current output is too low relative to our max output, or
601:             // if the current output is greater than the pair's token balance,
602:             // then we recurse on the left half (i.e. less items)
603:             if (
604:                 error != CurveErrorCodes.Error.OK || currentOutput < minOutputPerNumNFTs[(start + end) / 2 - 1] /* this is the max cost we are willing to pay, zero-indexed */
605:                     || currentOutput > pairTokenBalance
606:             ) {
607:                 end = (start + end) / 2 - 1;
608:             }
609:             // Otherwise, we recurse on the right half (i.e. more items)
610:             else {
611:                 numItemsToFill = (start + end) / 2;
612:                 start = (start + end) / 2 + 1;
613:                 priceToFillAt = currentOutput;
614:             }
615:         }
```
The protocol is designed to integrate various royalty info providers. Line 598 assumes the royalty amount is linear; however, this assumption can be violated, especially in the case of external royalty info providers who could be malicious and return a non-linear royalty amount.
For example, the royalty amount can be a function of the number of tokens to be swapped (e.g. greater/fewer royalties for a larger/smaller sale amount).
In this case, line 598 will be violated, and the max fillable functions will return incorrect `priceToFillAt` and `numItemsToFill`.

For example, `KODAV2` royalty calculation is NOT accurately linear to the input amount due to roundings.

```solidity
    function getKODAV2RoyaltyInfo(address _tokenAddress, uint256 _id, uint256 _amount)
        external
        view
        override
        returns (address payable[] memory receivers, uint256[] memory amounts)
    {
        // Get the edition the token is part of
        uint256 _editionNumber = IKODAV2(_tokenAddress).editionOfTokenId(_id);
        require(_editionNumber > 0, "Edition not found for token ID");

        // Get existing artist commission
        (address artistAccount, uint256 artistCommissionRate) = IKODAV2(_tokenAddress).artistCommission(_editionNumber);

        // work out the expected royalty payment
        uint256 totalRoyaltyToPay = (_amount / modulo) * creatorRoyaltiesFee;

        // Get optional commission set against the edition and work out the expected commission
        (uint256 optionalCommissionRate, address optionalCommissionRecipient) =
            IKODAV2(_tokenAddress).editionOptionalCommission(_editionNumber);
        if (optionalCommissionRate > 0) {
            receivers = new address payable[](2);
            amounts = new uint256[](2);

            uint256 totalCommission = artistCommissionRate + optionalCommissionRate;

            // Add the artist and commission
            receivers[0] = payable(artistAccount);
            amounts[0] = (totalRoyaltyToPay / totalCommission) * artistCommissionRate;//@audit-info rounding occurs here

            // Add optional splits
            receivers[1] = payable(optionalCommissionRecipient);
            amounts[1] = (totalRoyaltyToPay / totalCommission) * optionalCommissionRate;//@audit-info rounding occurs here
        } else {
            receivers = new address payable[](1);
            amounts = new uint256[](1);

            // Add the artist and commission
            receivers[0] = payable(artistAccount);
            amounts[0] = totalRoyaltyToPay;
        }

        return (receivers, amounts);
    }
```

If the royalty info provider returned higher royalty for a larger sale amount, the `priceToFillAt` will be higher than the actual sale.
Note that the `priceToFillAt` value calculated with the linearity assumption is used as a [minimum expected output parameter](https://github.com/sudoswap/lssvm2/blob/78d38753b2042d7813132f26e5573c6699b605ef/src/VeryFastRouter.sol#L351) for the function `ILSSVMPairERC721::swapNFTsForToken` within the swap sell logic. Similar reasoning holds for the swap-buy logic.

```solidity
VeryFastRouter.sol
345:                 // If we can sell at least 1 item...
346:                 if (numItemsToFill != 0) {
347:                     // If property checking is needed, do the property check swap
348:                     if (order.doPropertyCheck) {
349:                         outputAmount = ILSSVMPairERC721(address(order.pair)).swapNFTsForToken(
350:                             order.nftIds[:numItemsToFill],
351:                             priceToFillAt,//@audit-info min expected output
352:                             swapOrder.tokenRecipient,
353:                             true,
354:                             msg.sender,
355:                             order.propertyCheckParams
356:                         );
357:                     }
358:                     // Otherwise do a normal sell swap
359:                     else {
360:                         // Get subarray if ERC721
361:                         if (order.isERC721) {
362:                             outputAmount = order.pair.swapNFTsForToken(
363:                                 order.nftIds[:numItemsToFill], priceToFillAt, swapOrder.tokenRecipient, true, msg.sender
364:                             );
365:                         }
366:                         // For 1155 swaps, wrap as number
367:                         else {
368:                             outputAmount = order.pair.swapNFTsForToken(
369:                                 _wrapUintAsArray(numItemsToFill),
370:                                 priceToFillAt,
371:                                 swapOrder.tokenRecipient,
372:                                 true,
373:                                 msg.sender
374:                             );
375:                         }
376:                     }
377:                 }
```
Thus, the swap will fail if the `priceToFillAt` is calculated to be greater than the actual sale.

The Cyfrin team acknowledges that Sudoswap expects all collections to be ERC-2981 compliant, and EIP-2981 states that the royalty amount should be linear to the amount.
However, tokens can use a royalty lookup that is not compliant with EIP-2981 and can be abused to prevent honest users' valid transactions, so the protocol should not rely on the assumption that the royalty amount is linear.
```
The linearity assumption can be violated, especially in the case of external royalty info providers (possibly malicious), and this can lead to protocol failing to behave as expected, as legitimate swaps will fail.
Due to these incorrect assumptions affecting the core functions, we evaluate the severity to HIGH.

The amountDue calculation at the liquidateDefaultLoanWithIncentive function at the LenderCommitmentGroup contract calls getAmountOwedForBid with a false argument, which means it considers the principal lent as owed but not the interest that was accrued during the borrow period. This can be gamed by malicious users to avoid paying loans interest. Take a look at the getAmountOwedForBid function:
```solidity
function getAmountOwedForBid(uint256 _bidId, bool _includeInterest)
    public
    view
    virtual
    returns (uint256 amountOwed_)
{
    Payment memory amountOwedPayment = ITellerV2(TELLER_V2).getAmountOwedForBid(_bidId, _includeInterest);
    amountOwed_ = _includeInterest
        ? amountOwedPayment.principal + amountOwedPayment.interest
        : amountOwedPayment.principal;
}
```
Notice it will only return the principal amount if a false boolean is passed as the second argument of a call to it. At the liquidateDefaultedLoanWithIncentive function, this is exactly what happens:
```solidity
function liquidateDefaultedLoanWithIncentive(
    uint256 _bidId,
    int256 _tokenAmountDifference
) public bidIsActiveForGroup(_bidId) {
    uint256 amountDue = getAmountOwedForBid(_bidId, false);
    ...
}
```
This means the amountDue does not include interest. However, this is not on par with TellerV2 contract, as its liquidation function does repay both the owed principal and the interest. This can be seen at the following code snippet:
```solidity
function _liquidateLoanFull(uint256 _bidId, address _recipient)
    internal
    acceptedLoan(_bidId, "liquidateLoan")
{
    ...
    _repayLoan(
        _bidId,
        Payment({ principal: owedPrincipal, interest: interest }),
        owedPrincipal + interest,
        false
    );
    ...
}
```
Users can arbitrarily decide to liquidate repaying interest or not back to Teller lenders by liquidating via the TellerV2 contract or via LenderCommitmentGroups contracts. LenderCommitmentGroups's liquidation function spreads bad debt to the whole lending pool while benefitting the liquidator.

```solidity
Users can open a "Cost Share Request" (CSR) using the FairSideClaim contract's
openPWPRequest. The function checks that the account has purchased enough cost
share benefits for the claim amount requested. However, the cross share benefit
is checked against claim amount after taking a 10 percent haircut. Therefore a user
can request availableCostShareBenefits * 10/9 to pass the check and get 100
percent coverage.
The following are the relevant snippets for the issue:
• Cost share requests are opened using the openPWPRequest function.
• requestPayout is returned after haircutting 10% of claimAmount in validateCSR
• The CostShareRequest takes the returned requestPayout as the claimAmount
(what will be paid)
uint256 private constant NON_USA = 0.9 ether;
function openPWPRequest(uint256 claimAmount, uint256 coverId, bool inETH)
external payable onlyCoverIdOwner(coverId) {
    (uint256 requestPayout, uint256 availableCostShareBenefits) =
    validateCSR(claimAmount, coverId);
    createCostshareRequest(requestPayout, claimAmount, 0, coverId);
}

function validateCSR(uint256 claimAmount, uint256 coverId) private view
returns (uint256, uint256) {
    Membership memory account = fairSideNetwork.getMembership(coverId);
    // 90% of the full claim is paid out as 10% in the USA
    uint256 requestPayout = claimAmount.mul(NON_USA);
    if (account.availableCostShareBenefits < requestPayout) {
        revert FSClaims_CostRequestExceedsAvailableCostShareBenefits();
    }
    return (requestPayout, account.availableCostShareBenefits);
}

function createCostshareRequest(uint256 requestPayout, uint256 claimAmount,
uint256 _csrType, uint256 coverId) private {
    CostShareRequest memory csr = CostShareRequest(
        uint80(block.timestamp),
        msg.sender,
        coverId,
        _csrType,
        requestPayout,
        bytes32(0),
        ClaimStatus.IN_PROGRESS
    );
    costShareRequests[nextClaimId] = csr;
}
```
As seen above, requestPayout is 90% of the claimAmount:
```solidity
uint256 requestPayout = claimAmount.mul(NON_USA);
```
Then the requestPayout is checked against the member's cost share benefits:
```solidity
if (account.availableCostShareBenefits < requestPayout) {
    revert FSClaims_CostRequestExceedsAvailableCostShareBenefits();
}
```
Therefore if the user passes a claimAmount that after 10% haircut will be equal to
availableCostShareBenefits and pass the if statement, then requestPayout will be
equal to the entire cost share benefit. User will receive 100% coverage.
The amount of claimAmount needed is availableCostShareBenefits * 10/9.
For example, if user purchased 90 ETH cost share benefits: 90 ether * 10/9 = 100
ether.
Supplying 100 ether as claimAmount will bypass the user copay.
Loss of funds. 100% coverage instead of expected 90%

recommendation:
Consider changing the if statement to check against claimAmount instead:
```solidity
if (account.availableCostShareBenefits < claimAmount) {
    revert FSClaims_CostRequestExceedsAvailableCostShareBenefits();
}
```

description:
It is possible to prevent the launch of any ILO pool at any time, including pools that have reached their total raised amount. This can be done at any time and the cost for the attacker is negligible.

Not only this is a DOS of the whole protocol, but the attack can be performed at the very end of the sale, making users lose a lot on gas fees, considering it will be deployed on Ethereum Mainnet. Hundreds or thousands of users will participate in ILO pools via `buy()`, and will have to later call `claimRefund()` to get their “raise” tokens back.

Token launches that were deemed to be successful will be blocked after raising funds from many users, and this will most certainly affect the perception of the token, and its pricing on any attempt of a future launch/sale.

The `ILOManager` contract has a check to assert that the price at the time of the token launch is the same as the one initialized by the project. If they differ the transaction will revert, and the token launch will fail:

```solidity
function launch(address uniV3PoolAddress) external override {
  require(block.timestamp > _cachedProject[uniV3PoolAddress].launchTime, "LT");
  (uint160 sqrtPriceX96, , , , , , ) = IUniswapV3Pool(uniV3PoolAddress).slot0();
  require(_cachedProject[uniV3PoolAddress].initialPoolPriceX96 == sqrtPriceX96, "UV3P");
  address[] memory initializedPools = _initializedILOPools[uniV3PoolAddress];
  require(initializedPools.length > 0, "NP");
  for (uint256 i = 0; i < initializedPools.length; i++) {
    IILOPool(initializedPools[i]).launch();
  }

  emit ProjectLaunch(uniV3PoolAddress);
}
```

The problem is that `sqrtPriceX96` can be easily manipulated in Uniswap v3 Pools when there is no liquidity in it via a swap with no cost. In theory, this could be mitigated by anyone by swapping back to get back to the original price. But there is an additional problem which makes the severity of the attack even higher. The attacker can add [single-sided liquidity](https://support.uniswap.org/hc/en-us/articles/20902968738317-What-is-single-sided-liquidity#:~:text=When%20you%20select%20a%20range%20that%20is%20outside%20the%20current%20price%20range%2C%20you%20will%20only%20be%20able%20to%20supply%20one%20of%20the%20two%20tokens.) to the pool (just the Raise Token) after the price was manipulated.

When you select a range that is outside the current price range, you will only be able to supply one of the two tokens.

By adding liquidity in ticks greater than the manipulated price, but lower than the expected initial price, it would require the swapper to provide some `SALE_TOKEN`, which should not be available at this moment, since they should all be in the ILO pool.

Even if the project admin has some `SALE_TOKEN`, the attacker can mint a higher amount of liquidity by providing more single-sided `RAISE_TOKEN` liquidity, making the needed amount of `SALE_TOKEN` even higher.

recommendation:
Since the price can be manipulated, and single-sided liquidity can be minted, getting the price back to its initial price would require swapping and providing `SALE_TOKEN`. Since it’s an initial sale with vesting for other participants, it is expected that no parties hold the token. But, even if they do, the attack can be performed at some cost anyway as explained before.

So one possible solution could be to reserve some amount in the ILO pool in case it needs to be swapped back, and perform a swap before the liquidity is added to the Uniswap Pool, taking into account an amount that would make the attack very expensive to rollback. Another approach could involve having a wrapper token around the `SALE_TOKEN` that can be minted and swapped to reach the expected price.

This is a potential first step. Additional considerations shall be taken into account, like an attacker minting liquidity on various tick ranges, which may also affect calculations.

**Proof of Concept:**
```solidity
The following Proof of Concept shows how an attacker can make a launch revert after raising capital, at the cost of providing liquidity with only `1 wei` of USDC (Raise Token).

Console Output:

```
<<Minting Attack>>
<<Failed mitigation attempt>>

uniswapV3SwapCallback()
  amount0 (USDC)       0
  amount1 (SALE_TOKEN) 1
```

This would be enough to perform an attack that can’t be reverted in most cases since no other sale tokens should be circulating before the launch. But for the sake of interest, the minted liquidity and the mitigation amount can be increased to check the values needed to get back to the initial price in different situations.

POC:

  1. Add the import to the top of `test/ILOManager.t.sol`.
  2. Add the test to the `ILOManagerTest` contract in `test/ILOManager.t.sol`.
  3. Run `forge test --mt testManipulatePriceForLaunch -vv`.

```solidity
import "../lib/v3-core/contracts/interfaces/IUniswapV3Pool.sol";
import "forge-std/console.sol";

function testManipulatePriceForLaunch() external {
  IILOManager.InitPoolParams memory params = _getInitPoolParams();
  _initPool(PROJECT_OWNER, params);

  assertEq(IUniswapV3Pool(projectId).token0(), USDC);
  assertEq(IUniswapV3Pool(projectId).token1(), SALE_TOKEN);

  vm.label(USDC, "USDC");
  vm.label(SALE_TOKEN, "SALE_TOKEN");
  vm.label(projectId, "UNI_V3_POOL");
  vm.label(address(this), "ATTACKER");

  unsuccessfulPriceManipulation();

  priceManipulationAttack();

  vm.warp(LAUNCH_START+1);
  vm.expectRevert(bytes("UV3P"));
  iloManager.launch(projectId);
}

function unsuccessfulPriceManipulation() internal {
  uint160 initialPrice = mockProject().initialPoolPriceX96;
  uint160 MIN_SQRT_RATIO = 4295128739 + 1;

  // Check price before attack
  (uint160 sqrtPriceX96, , , , , , ) = IUniswapV3Pool(projectId).slot0();
  assertEq(uint256(sqrtPriceX96), initialPrice);

  // Attack
  IUniswapV3Pool(projectId).swap(address(this), true, 1, MIN_SQRT_RATIO, "");
  (sqrtPriceX96, , , , , , ) = IUniswapV3Pool(projectId).slot0();
  assertEq(uint256(sqrtPriceX96), MIN_SQRT_RATIO);

  // Mitigation
  IUniswapV3Pool(projectId).swap(address(this), false, 1, initialPrice, "");
  (sqrtPriceX96, , , , , , ) = IUniswapV3Pool(projectId).slot0();
  assertEq(uint256(sqrtPriceX96), initialPrice);
}

function priceManipulationAttack() internal {
  uint160 initialPrice = mockProject().initialPoolPriceX96;
  uint160 MIN_SQRT_RATIO = 4295128739 + 1;

  // Check price before attack
  (uint160 sqrtPriceX96, , , , , , ) = IUniswapV3Pool(projectId).slot0();
  assertEq(uint256(sqrtPriceX96), initialPrice);

  // Attack -> Swap to manipulate price
  IUniswapV3Pool(projectId).swap(address(this), true, 1, MIN_SQRT_RATIO, "");
  (sqrtPriceX96, , , , , , ) = IUniswapV3Pool(projectId).slot0();
  assertEq(uint256(sqrtPriceX96), MIN_SQRT_RATIO);

  // Attack -> Mint to prevent swapping back
  console.log("\n<<Minting Attack>>");
