When User B calls the following `propose` function for creating a proposal, it checks that User B’s prior number of votes at the relevant block is larger than the proposal threshold through executing `nouns.getPriorVotes(msg.sender, block.number - 1) > temp.proposalThreshold`. This means that User B cannot create the proposal when the prior number of votes and the proposal threshold are the same.

```solidity
function propose(
    address[] memory targets,
    uint256[] memory values,
    string[] memory signatures,
    bytes[] memory calldatas,
    string memory description
) public returns (uint256) {
    ProposalTemp memory temp;

    temp.totalSupply = nouns.totalSupply();

    temp.proposalThreshold = bps2Uint(proposalThresholdBPS, temp.totalSupply);

    require(
        nouns.getPriorVotes(msg.sender, block.number - 1) > temp.proposalThreshold,
        'NounsDAO::propose: proposer votes below proposal threshold'
    );
    require(
        targets.length == values.length &&
            targets.length == signatures.length &&
            targets.length == calldatas.length,
        'NounsDAO::propose: proposal function information arity mismatch'
    );
    require(targets.length != 0, 'NounsDAO::propose: must provide actions');
    require(targets.length <= proposalMaxOperations, 'NounsDAO::propose: too many actions');

    temp.latestProposalId = latestProposalIds[msg.sender];
    if (temp.latestProposalId != 0) {
        ProposalState proposersLatestProposalState = state(temp.latestProposalId);
        require(
            proposersLatestProposalState != ProposalState.Active,
            'NounsDAO::propose: one live proposal per proposer, found an already active proposal'
        );
        require(
            proposersLatestProposalState != ProposalState.Pending,
            'NounsDAO::propose: one live proposal per proposer, found an already pending proposal'
        );
    }

    temp.startBlock = block.number + votingDelay;
    temp.endBlock = temp.startBlock + votingPeriod;

    proposalCount++;
    Proposal storage newProposal = _proposals[proposalCount];
    newProposal.id = proposalCount;
    newProposal.proposer = msg.sender;
    newProposal.proposalThreshold = temp.proposalThreshold;
    newProposal.eta = 0;
    newProposal.targets = targets;
    newProposal.values = values;
    newProposal.signatures = signatures;
    newProposal.calldatas = calldatas;
    newProposal.startBlock = temp.startBlock;
    newProposal.endBlock = temp.endBlock;
    newProposal.forVotes = 0;
    newProposal.againstVotes = 0;
    newProposal.abstainVotes = 0;
    newProposal.canceled = false;
    newProposal.executed = false;
    newProposal.vetoed = false;
    newProposal.totalSupply = temp.totalSupply;
    newProposal.creationBlock = block.number;

    latestProposalIds[newProposal.proposer] = newProposal.id;

    /// @notice Maintains backwards compatibility with GovernorBravo events
    emit ProposalCreated(
        newProposal.id,
        msg.sender,
        targets,
        values,
        signatures,
        calldatas,
        newProposal.startBlock,
        newProposal.endBlock,
        description
    );

    /// @notice Updated event with `proposalThreshold` and `minQuorumVotes`
    /// @notice `minQuorumVotes` is always zero since V2 introduces dynamic quorum with checkpoints
    emit ProposalCreatedWithRequirements(
        newProposal.id,
        msg.sender,
        targets,
        values,
        signatures,
        calldatas,
        newProposal.startBlock,
        newProposal.endBlock,
        newProposal.proposalThreshold,
        minQuorumVotes(),
        description
    );

    return newProposal.id;
}
```

After User B’s proposal is created, User A can call the following `cancel` function to cancel it. When calling `cancel`, it checks that User B’s prior number of votes at the relevant block is less than the proposal threshold through executing `nouns.getPriorVotes(proposal.proposer, block.number - 1) < proposal.proposalThreshold`. When User B’s prior number of votes and the proposal threshold are the same, User A cannot cancel this proposal of User B. However, this contradicts the fact User B actually cannot create this proposal when the same condition holds true. In other words, if User B cannot create this proposal when the prior number of votes and the proposal threshold are the same, User A should be able to cancel User B’s proposal under the same condition but it is not true. The functionality for canceling User B’s proposal in this situation becomes unavailable for User A.

```solidity
function cancel(uint256 proposalId) external {
    require(state(proposalId) != ProposalState.Executed, 'NounsDAO::cancel: cannot cancel executed proposal');

    Proposal storage proposal = _proposals[proposalId];
    require(
        msg.sender == proposal.proposer ||
            nouns.getPriorVotes(proposal.proposer, block.number - 1) < proposal.proposalThreshold,
        'NounsDAO::cancel: proposer above threshold'
    );

    proposal.canceled = true;
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        timelock.cancelTransaction(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i],
            proposal.eta
        );
    }

    emit ProposalCanceled(proposalId);
}
```

The function recoverERC20 is very privileged. It means to recover any token that is accidently sent to the contract.

```solidity
function recoverERC20(address token) external onlyOwner returns(bool) {
	if(minAmountRewardToken[token] != 0) revert Errors.CannotRecoverToken();

	uint256 amount = IERC20(token).balanceOf(address(this));
	if(amount == 0) revert Errors.NullValue();
	IERC20(token).safeTransfer(owner(), amount);

	return true;
}
```

However, admin / owner can use this function to transfer all the reserved reward tokens, which result in fund loss of the pledge creator and the loss of reward for users that want to delegate the veToken.

Also, the recovered token is sent to owner directly instead of sending to a recipient address.

The safeguard

```solidity
if(minAmountRewardToken[token] != 0)
```

cannot stop owner transferring funds because if the owner is compromised or misbehaves, he can adjust the whitelist easily.

recommendation:
We recommend that the project uses a multisig wallet to safeguard the owner’s wallet.

We can also keep track of the reserved amount for rewarding token and only transfer the remaining amount of token out.

```solidity
pledgeAvailableRewardAmounts[pledgeId] += totalRewardAmount;
reservedReward[token] += totalRewardAmount;
```

Then we can change the implementation to:

```solidity
function recoverERC20(address token, address recipient) external onlyOwner returns(bool) {

	uint256 amount = IERC20(token).balanceOf(address(this));
	if(amount == 0) revert Errors.NullValue();

	if(minAmountRewardToken[token] == 0) {
	 // if it is not whitelisted, we assume it is mistakenly sent, 
	   // we transfer the token to recipient
	 IERC20(token).safeTransfer(recipient, amount);
	} else {
	// revert if the owner over transfer
	if(amount >  reservedReward[token]) revert rewardReserved();
	  IERC20(token).safeTransfer(recipient, amount - reservedReward[token]);
	}

	return true;

}
```

