        IProfile.SProfile memory newSProfile = profile.profileOf(John);
        address newSponsor = newSProfile.sponsor;
        assertTrue(newSponsor == Alice);
        console.log("Sponsor after Eve staked 6x more than Alice: ", newSponsor);
    }
