SafeERC20.safeTransfer(REWARD_TOKEN, _tipReceiver, _requestedTip);
+
deposit.scaledUnclaimedRewardCheckpoint =
+
deposit.scaledUnclaimedRewardCheckpoint - (_requestedTip * SCALE_FACTOR);
