**Proof of Concept:**
```solidity
function anyExecute(bytes calldata data)
    external
    virtual
    requiresExecutor
    returns (bool success, bytes memory result)
{
    uint256 _initialGas = gasleft();
    uint24 fromChainId;
    UserFeeInfo memory _userFeeInfo;

    if (localAnyCallExecutorAddress == msg.sender) {
        initialGas = _initialGas;
        (, uint256 _fromChainId) = _getContext();
        fromChainId = _fromChainId.toUint24();

        _userFeeInfo.depositedGas = _gasSwapIn(
            uint256(uint128(bytes16(data[data.length - PARAMS_GAS_IN:data.length - PARAMS_GAS_OUT]))), fromChainId).toUint128();
        _userFeeInfo.gasToBridgeOut = uint128(bytes16(data[data.length - PARAMS_GAS_OUT:data.length]));
    } else {
        fromChainId = localChainId;
        _userFeeInfo.depositedGas = uint128(bytes16(data[data.length - 32:data.length - 16]));
        _userFeeInfo.gasToBridgeOut = _userFeeInfo.depositedGas;
    }

    if (_userFeeInfo.depositedGas < _userFeeInfo.gasToBridgeOut) {
        _forceRevert();
        return (true, "Not enough gas to bridge out");
    }

    userFeeInfo = _userFeeInfo;

    // execution part
    ............

    if (initialGas > 0) {
        _payExecutionGas(userFeeInfo.depositedGas, userFeeInfo.gasToBridgeOut, _initialGas, fromChainId);
    }
}
```

To implement the attack, the attacker can call `callOutSigned` on a branch chain to bypass `lock`. On the root chain, the `virtual account` makes three external calls:

1. `retryDeposit` at `Arbitrum Branch Bridge Agent` with an already executed nonce. The call will `forceRevert()` and `initialGas` will be non-zero since it has not been modified by reentering. As a result, all of the execution gas budget will be withdrawn.

```solidity
function _forceRevert() internal {
    if (initialGas == 0) revert GasErrorOrRepeatedTx();

    IAnycallConfig anycallConfig = IAnycallConfig(IAnycallProxy(localAnyCallAddress).config());
    uint256 executionBudget = anycallConfig.executionBudget(address(this));

    // Withdraw all execution gas budget from anycall for tx to revert with "no enough budget"
    if (executionBudget > 0) try anycallConfig.withdraw(executionBudget) {} catch {}
}
```

2. `callOut` at `Arbitrum Branch Bridge Agent`. The call should succeed and `initialGas` is deleted.

```solidity
function _payExecutionGas(uint128 _depositedGas, uint128 _gasToBridgeOut, uint256 _initialGas, uint24 _fromChain) internal {
    delete(initialGas);
    delete(userFeeInfo);

    if (_fromChain == localChainId) return;
```

3. Directly deposit a small amount of gas at `Anycall Config`, to ensure the success of the transaction.

```solidity
function deposit(address _account) external payable {
    executionBudget[_account] += msg.value;
    emit Deposit(_account, msg.value);
}
```

Then, the original call proceeds and `_payExecutionGas` will be skipped. The call will succeed with all withdrawn gas budgets permanently frozen. In current implementation, ETH can be sweeped to the DAO address, but this is another mistake, as `sweep` should transfer WETH instead.

description:
The DebitaIncentives::updateFunds function iterates over the lenders array, verifying whether the principle and collateral pair for each lend offer is whitelisted. If a non-whitelisted pair is encountered, the function exits prematurely, causing it to skip the processing of all subsequent pairs, even if they are valid and whitelisted. This causes the loss of potential funds for lenders and borrowers, as they would have been eligible to claim incentives had the function processed all valid pairs. Specifically, the lentAmountPerUserPerEpoch, totalUsedTokenPerEpoch, and borrowAmountPerEpoch mappings are not updated. In DebitaIncentives.sol#L317 the return keyword is used, stopping the entire function, not just the iteration, ignoring the subsequent elements in the informationOffers array.

Internal pre-conditions
• At least one lend offer be active with the following conditions (non-whitelisted pair lend offer):
– principle and acceptedCollaterals pair is not whitelisted in the DebitaIncentives contract.
– lonelyLender must be false.
– availableAmount is greater than 0.
• At least one lend offer be active with the following conditions (whitelisted pair lend offer):
– principle and acceptedCollaterals pair is whitelisted in the DebitaIncentives contract.
– lonelyLender must be false.
– availableAmount is greater than 0.
• At least one borrow order must be active with the following conditions:
– acceptedPrinciples must include at least a whitelisted principle and at least a non-whitelisted principle.
– collateral when paired with the principle, it must be whitelisted.
– availableAmount is greater than 0.
• The terms of the borrow order must allow it to be successfully matched with both types of lend offers in a single DebitaV3Aggregator::matchOffersV3 call.
• DebitaV3Aggregator must not be paused.

External pre-conditions

Attack Path
1. DebitaIncentives contract owner whitelists pair of principle and collateral calling DebitaIncentives::whitelListCollateral
2. A user calls DebitaIncentives::incentivizePair to incentivize the already whitelisted principle. This function transfers the tokens given as incentives from the user to the DebitaIncentives contract. The amount of incentives is updated:  
contracts/contracts/DebitaIncentives.sol#L277-L285  
```solidity
if (lendIncentivize[i]) {
    lentIncentivesPerTokenPerEpoch[principle][
        hashVariables(incentivizeToken, epoch)
    ] += amount;
} else {
    borrowedIncentivesPerTokenPerEpoch[principle][
        hashVariables(incentivizeToken, epoch)
    ] += amount;
}
```
3. Another user calls DebitaV3Aggregator::matchOffersV3 to match a previously created borrow order with one lend offer that has a non-whitelisted pair and another lend offer that has a whitelisted pair. Inside matchOffersV3, the DebitaIncentives::updateFunds function is called to update the funds of the lenders and borrowers. offers array contains the principle of each accepted lend offer, and it is passed as an argument.  
contracts/contracts/DebitaV3Aggregator.sol#L631-L636  
```solidity
DebitaIncentives(s_Incentives).updateFunds(
    offers,
    borrowInfo.collateral,
    lenders,
    borrowInfo.owner
);
```
updateFunds function iterates over the array, and checks if the principle and collateral pair is whitelisted. If the pair is not whitelisted, the return keyword halts the entire function. The offer containing the non-whitelisted principle is at index 0, so the function stops before the iteration reaches the offer at index 1 that has the whitelisted principle. This stops lentAmountPerUserPerEpoch, totalUsedTokenPerEpoch and borrowAmountPerEpoch from being updated.  
contracts/contracts/DebitaIncentives.sol#L306-L341  
```solidity
function updateFunds(
    infoOfOffers[] memory informationOffers,
    address collateral,
    address[] memory lenders,
    address borrower
) public onlyAggregator {
    for (uint i = 0; i < lenders.length; i++) {
        bool validPair = isPairWhitelisted[informationOffers[i].principle][
            collateral
        ];
        if (!validPair) {
            return;
        }
        address principle = informationOffers[i].principle;
        uint _currentEpoch = currentEpoch();
        lentAmountPerUserPerEpoch[lenders[i]][
            hashVariables(principle, _currentEpoch)
        ] += informationOffers[i].principleAmount;
        totalUsedTokenPerEpoch[principle][
            _currentEpoch
        ] += informationOffers[i].principleAmount;
        borrowAmountPerEpoch[borrower][
            hashVariables(principle, _currentEpoch)
        ] += informationOffers[i].principleAmount;
        emit UpdatedFunds(
            lenders[i],
            principle,
            collateral,
            borrower,
            _currentEpoch
        );
    }
}
```
As the mappings are not updated, the beneficiary lender or borrower can't claim the incentives:  
DebitaIncentives::claimIncentives#L152-L154  
```solidity
uint lentAmount = lentAmountPerUserPerEpoch[msg.sender][
    hashVariables(principle, epoch)
];
```
DebitaIncentives::claimIncentives#L164-L166  
```solidity
uint borrowAmount = borrowAmountPerEpoch[msg.sender][
    hashVariables(principle, epoch)
];
```
DebitaIncentives::claimIncentives#L170-L173  
```solidity
require(
    borrowAmount > 0 || lentAmount > 0,
    "No borrowed or lent amount"
);
```
Permanent loss of funds for lenders and borrowers who would have been eligible to claim incentives for a given epoch.

recommendation:
Change the return keyword in DebitaIncentives::addFunds  
```solidity
function updateFunds(
    infoOfOffers[] memory informationOffers,
    address collateral,
    address[] memory lenders,
    address borrower
) public onlyAggregator {
    for (uint i = 0; i < lenders.length; i++) {
        bool validPair = isPairWhitelisted[informationOffers[i].principle][
            collateral
        ];
        if (!validPair) {
            continue;
        }
        address principle = informationOffers[i].principle;
        uint _currentEpoch = currentEpoch();
        lentAmountPerUserPerEpoch[lenders[i]][
            hashVariables(principle, _currentEpoch)
        ] += informationOffers[i].principleAmount;
        totalUsedTokenPerEpoch[principle][
            _currentEpoch
        ] += informationOffers[i].principleAmount;
        borrowAmountPerEpoch[borrower][
            hashVariables(principle, _currentEpoch)
        ] += informationOffers[i].principleAmount;
        emit UpdatedFunds(
            lenders[i],
            principle,
            collateral,
            borrower,
            _currentEpoch
        );
    }
}
```
