After borrowing GT tokens, the borrower can repay their debt using their collateral
with the flashRepay function if they wish to do so.
```solidity
function flashRepay(
uint256 id,
bytes calldata callbackData
) external override nonReentrant {
GtConfig memory config = _config;
if (config.maturity <= block.timestamp) {
revert GtIsExpired(id);
}
LoanInfo memory loan = loanMapping[id];
