    if (IS_TOKEN1_QUOTE_IN_BASE_POOL) {
        // TOKEN0(POOL) -> TOKEN1(POOL)
        price0 = VelodromeUtils.amount1(BASE0, BASE0, BASE1, r0, r1, IS_BASE_POOL_STABLE);
        if (IS_TOKEN1_QUOTE_IN_QUOTE_POOL) {
            // TOKEN1(POOL) -> TOKEN1(QUOTE_POOL)
            price0 = VelodromeUtils.amount1(price0, BASE1, QUOTE_BASE, qr0, qr1, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
            price1 = VelodromeUtils.amount1(BASE1, BASE1, QUOTE_BASE, qr0, qr1, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
        } else {
            // TOKEN1(POOL) -> TOKEN0(QUOTE_POOL)
            price0 = VelodromeUtils.amount0(price0, BASE1, QUOTE_BASE, qr1, qr0, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
            price1 = VelodromeUtils.amount0(BASE1, BASE1, QUOTE_BASE, qr1, qr0, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
        }
    } else {
        // TOKEN1(POOL) -> TOKEN0(POOL)
        price1 = VelodromeUtils.amount0(BASE1, BASE0, BASE1, r0, r1, IS_BASE_POOL_STABLE);
        if (IS_TOKEN1_QUOTE_IN_QUOTE_POOL) {
            // TOKEN0(POOL) -> TOKEN1(QUOTE_POOL)
            price0 = VelodromeUtils.amount1(BASE0, BASE0, QUOTE_BASE, qr0, qr1, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
            price1 = VelodromeUtils.amount1(price1, BASE0, QUOTE_BASE, qr0, qr1, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
        } else {
            // TOKEN0(POOL) -> TOKEN0(QUOTE_POOL)
            price0 = VelodromeUtils.amount0(BASE1, BASE0, QUOTE_BASE, qr1, qr0, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
            price1 = VelodromeUtils.amount0(price1, BASE0, QUOTE_BASE, qr1, qr0, IS_QUOTE_POOL_STABLE) * QUOTE_PRICE_FACTOR;
        }
    }
    _value0 = _amount0 * price0 / BASE0;
    _value1 = _amount1 * price1 / BASE1;
}
```

Some DApps can take advantage of an atomic deployment by utilising a “factory” contract to bundle the deployment and setup of multiple contracts into a single transaction. This ensures no other transaction can affect a partially deployed DApp. However, due to the large number of contracts that must be deployed during setup, this method is not feasible for Rocket Pool.

1A TruffleSuite migration defined at rocketpool/migrations/2_deploy_contracts.js

Rocket Pool Protocol Review

State changing operations in RocketStorage are protected by the onlyLatestRocketNetworkContract() modifier, which consists of the following check:

```solidity
if (boolStorage[keccak256(abi.encodePacked("contract.storage.initialised"))] == true) {
    // Make sure the access is permitted to only contracts in our Dapp
    require(boolStorage[keccak256(abi.encodePacked("contract.exists", msg.sender))], "Invalid or outdated network contract");
}
```

The testing team recommend changing this modifier to contain a check equivalent to the following:

```solidity
if (boolStorage[keccak256(abi.encodePacked("contract.storage.initialised"))] == true) {
    // Make sure the access is permitted to only contracts in our Dapp
    require(boolStorage[keccak256(abi.encodePacked("contract.exists", msg.sender))], "Invalid or outdated network contract");
} else {
    // Only Dapp and the guardian account are allowed access during initialisation.
    require(
        boolStorage[keccak256(abi.encodePacked("contract.exists", msg.sender))] ||
        boolStorage[keccak256(abi.encodePacked("access.role", "guardian", msg.sender))
    ), "Invalid or outdated network contract");
}
```

This would allow the deployer account direct access to storage during initialisation while appropriately preventing interference by an external attacker. The additional gas costs incurred by adding such a check would only be experienced during deployment.

In order to allow deployed contracts to make storage changes in their constructor, the existing migration script would need to be modified to register the contract with RocketStorage prior to deployment. This would involve pre-calculating the address of the new contract from an appropriate nonce value, or deploying via a factory contract using the CREATE2 opcode. This pre-calculation is somewhat complicated but achievable (provided the deployer account is not used for unrelated transactions during the course of deployment).

A simpler alternative could be to instead authenticate the "guardian" via tx.origin, but this has its own safety concerns. This would allow contracts deployed by the "guardian" to modify storage without needing to be pre-registered, but would be unsafe should the deployer account interact with any external contracts during the deployment.

description:
```solidity
The checkInvariants() function of the InvariantCheck contract is called via the modifiers checkInvariantsBeforeFunction() and checkInvariantsAfterFunction() of both LeveragedPool and PoolCommitter contracts, and it is meant to pause the contracts if the invariant checks don’t hold.
The aforementioned modifiers also contain the require(!paused, "Pool is paused"); statement, which reverts the entire transaction and resets the paused variable that was just set.
Furthermore, the paused state can only be set by the InvariantCheck contract due to the onlyInvariantCheckContract modifier. Thus the paused variable will never be set to true, making withdrawQuote() impossible to be executed because it requires the contract to be paused.
This means that the quote tokens will always stay in the pool even if invariants don’t hold and all other actions are blocked.
Relevant parts of the code:
The checkInvariants() function calls InvariantCheck.pause() if the invariants don’t hold.
The latter calls pause() in LeveragedPool and PoolCommitter:
contract InvariantCheck is IInvariantCheck {
    function checkInvariants(address poolToCheck) external override {
        ...
        pause(IPausable(poolToCheck), IPausable(address(poolCommitter)));
        ...
    }
    function pause(IPausable pool, IPausable poolCommitter) internal {
        pool.pause();
        poolCommitter.pause();
    }
}
In LeveragedPool and PoolCommitter contracts, the checkInvariantsBeforeFunction() and checkInvariantsAfterFunction() modifiers will make the transaction revert if checkInvariants() sets the paused state.
contract LeveragedPool is ILeveragedPool, Initializable, IPausable {
    modifier checkInvariantsBeforeFunction() {
        invariantCheck.checkInvariants(address(this)); // can set paused to true
        require(!paused, "Pool is paused"); // will reset pause again
        _;
    }
    modifier checkInvariantsAfterFunction() {
        require(!paused, "Pool is paused");
        _;
        invariantCheck.checkInvariants(address(this)); // can set paused to true
        require(!paused, "Pool is paused"); // will reset pause again
    }
    function pause() external override onlyInvariantCheckContract {
        // can only called from InvariantCheck
        paused = true;
        emit Paused();
    }
}
contract PoolCommitter is IPoolCommitter, Initializable {
    modifier checkInvariantsBeforeFunction() {
        invariantCheck.checkInvariants(leveragedPool); // can set paused to true
        require(!paused, "Pool is paused");
        // will reset pause again
        _;
    }
    modifier checkInvariantsAfterFunction() {
        require(!paused, "Pool is paused");
        _;
        invariantCheck.checkInvariants(leveragedPool); // can set paused to true
        require(!paused, "Pool is paused"); // will reset pause again
    }
    function pause() external onlyInvariantCheckContract {
        // can only called from InvariantCheck
        paused = true;
        emit Paused();
    }
}
```

recommendation:
```solidity
This issue is also discussed in modifiers-undermine-contract-pausing and there are a few reasons to reconsider fixing it:
• When a transaction triggers an invariant check and it is rolled back due to the revert, other transactions might still be executed. With a paused state this wouldn’t happen.
• Pause functionality that doesn’t work is misleading for developers and code reviewers. It is better to delete the dead code, which also saves gas.
• withdrawQuote() cannot be executed since the pause state is unreachable.
If it is preferable to use the pause functionality, it can be done by having a surrounding contract which stores the pause state and calls the underlying logic with a try mechanism. The underlying logic can then be reverted while the surrounding contract keeps the paused state.
Here is an implementation example of a surrounding contract that handles the revert and sets the pause variable.
The code that checks the invariants reverts with the InvariantsFail() custom error, which is caught by the try/catch block in the caller and the paused state is set.
//SPDX-License-Identifier: MIT
pragma solidity 0.8.11;
import "hardhat/console.sol";
contract Pool {
    error InvariantsFail();
    function DoSomething() public pure {
        revert InvariantsFail();
    }
}
contract InvariantCheck {
    Pool myPool = new Pool();
    bool pause;
    function TryDoSomething() public returns (string memory) {
        try myPool.DoSomething() { return "Ok"; }
        catch Error(string memory reason) { return reason; }
        catch Panic(uint) { return "Panic"; }
        catch (bytes memory reason) {
            if (bytes4(reason) == bytes4(abi.encodeWithSignature("InvariantsFail()"))) {
                pause = true;
                return("InvariantsFail");
            }
            return "Unknown";
        }
    }
    constructor() {
        console.log("Pause =",pause);
        console.log(TryDoSomething());
        console.log("Pause =",pause);
    }
}
```

description:
When liquidating an account, if the account has positive PnL, that amount of PnL is not minted to the account because all of its positions will be closed, so, such positive PnL will be lost to the TradingAccount, but, that PnL will also be lost to the MarginCollateralRecipient.

Let's break into two the explanation of this bug, first, let's explore what should happen when an account has a positive PnL, and then, we'll explore how margin is deducted from the account's collateralBalance.

So, when an account has positive PnL, the TradingAccount receives a deposit equivalent amount of USDZ into his collateralMarginBalance to the amount of positive PnL, and, the PerpetualEngine contract gets minted the exact same amount that was deposited into the TradingAccount, in this way, the deposited USDZ is indeed backed by the underlying token.

Now, when the margin is deducted from an account, the TradingAccount.deductAccountMargin() function iterates over the collateralLiquidationPriority attempting to deduct/seize collateral from the TradingAccount, and such collateral is transferred to a specific recipient depending if its deducting settlementFee, orderFee or PnL. The key to understanding here is that this amount comes out of the TradingAccount collateralBalance.

For example, if there is an account that has 100 USD in WETH, and, 50 USD in USDC as collateral, and, is required to deduct 125 USD from this account, the deductMargin will take 125 USD worth of the collateral owned by the account. In the end, the account will have 25 leftover USD in collateral, wether in WETH or USDC, what matters is that the account will have 25 USD as leftover, meaning, the account had enough collateral to cover the required amount to be deducted.

The problem caused by not minting the positive PnL to the liquidated accounts is that the PnL (when positive) is considered as if the account would have that USD value as deposited collateral in its account, but, when a position is liquidated and its positive PnL is not minted to the account, the margin that can be deducted would be at most the value of the account's collateral, which, as we'll see in the below examples, it could be lower than the amount to be deducted.

Consider an account that has multiple positions that are profitable and has yielded 300 positive PnL. Now, let's make an example of when the value of the collateral backing this account goes down and the account falls into liquidation.

Even though the loanToValue of the account's collateral is way lower than the requiredMaring, the huge positive PnL prevents the account from being liquidated because the marginBalance, after adding the positive PnL to the collateral's loanToValue is > requiredMargin.
Account is not liquidable because the big positive PnL prevented the account marginBalance to be lower than the requiredMargin.

requiredMarging:  1000
PnL:               300

marginBalance:    750 + 300 ===> 1050

loanToValue:      750
RealMarketValue:  1000

Now, let's see what happens when the value of the collateral drops a little bit more.
Account is now liquidable. But, the account only has collateral worth 900 USD, which means, the most amount of collateral (without the PnL) that will be transferred to the respective recipients will be 900USD, even though the amount to deduct is 1000.
This means that the positive PnL that was generated while the position was opened is completely lost, and the liquidator's recipients receive way less USD (900 USD) than what they should have received (1000 USD)

requiredMarging:  1000
PnL:               300

marginBalance:    675 + 300 ===> 975

loanToValue:      675
RealMarketValue:  900

As we've seen, the liquidator's recipient received way less USD value than what they should have, and not even mention that the liquidated account lost an extra 300 USD because all the deducted USD was from its deposited collateral, regardless that the account generated a profit of 300 USD. The account in reality had a total market value of 1200 USD, (900 USD worth of its collateral, and 300 USD of positive PnL), and, in the end, the account got deducted all of its collateral (900 USD), and did not receive any of its positive PnL (300 USD).

As we can see in the below snippet, the LiquidationBranch.liquidateAccounts() function does not mint the positive PnL before deducting collateral from the account.

```solidity
function liquidateAccounts(uint128[] calldata accountsIds) external {
    ...

    for (uint256 i; i < accountsIds.length; i++) {
        ...

        // get account's required maintenance margin & unrealized PNL
        (, UD60x18 requiredMaintenanceMarginUsdX18, SD59x18 accountTotalUnrealizedPnlUsdX18) =
            tradingAccount.getAccountMarginRequirementUsdAndUnrealizedPnlUsd(0, SD59x18_ZERO);

        // get then save margin balance into working data
        ctx.marginBalanceUsdX18 = tradingAccount.getMarginBalanceUsd(accountTotalUnrealizedPnlUsdX18);

        // if account is not liquidatable, skip to next account
        // account is liquidatable if requiredMaintenanceMarginUsdX18 > ctx.marginBalanceUsdX18
        if (!TradingAccount.isLiquidatable(requiredMaintenanceMarginUsdX18, ctx.marginBalanceUsdX18)) {
            continue;
        }

        //@audit-issue => Positive PnL has not been minted to the account, and the liquidation execution directly proceeds to deduct margin from the account's collateral.

        // deduct maintenance margin from the account's collateral
        // settlementFee = liquidationFee
        ctx.liquidatedCollateralUsdX18 = tradingAccount.deductAccountMargin({
            feeRecipients: FeeRecipients.Data({
                marginCollateralRecipient: globalConfiguration.marginCollateralRecipient,
                orderFeeRecipient: address(0),
                settlementFeeRecipient: globalConfiguration.liquidationFeeRecipient
            }),
            pnlUsdX18: requiredMaintenanceMarginUsdX18,
            orderFeeUsdX18: UD60x18_ZERO,
            settlementFeeUsdX18: ctx.liquidationFeeUsdX18
        });

        ...
    }
}
```

Positive PnL on liquidated accounts is completely lost. Accounts will get deducted more than what they should, and the liquidator's recipient would end up receiving way less USD than what they should.

recommendation:
Similar to SettlementBranch._fillOrder() function, before deducting margin, verify if there is a positive PnL, if so, deposit that amount of PnL into the TradingAccount, and mint USDZ to the PerpetualEngine contract.
In this way, when the liquidation execution reaches the point of deducting margin, the account will already have the positive PnL on its collateralBalance in the form of USDZ.
This will allow the deduct margin function to deduct that USDZ from the account and transfer it to the liquidator's recipient.
This also ensures that the liquidated account gets deducted the exact amount that should be deducted, because now, that positive PnL is also part of the account's collateralBalance.

```solidity
function liquidateAccounts(uint128[] calldata accountsIds) external {
    ...

    for (uint256 i; i < accountsIds.length; i++) {
        ...

        // get account's required maintenance margin & unrealized PNL
            (, UD60x18 requiredMaintenanceMarginUsdX18, SD59x18 accountTotalUnrealizedPnlUsdX18) =
                tradingAccount.getAccountMarginRequirementUsdAndUnrealizedPnlUsd(0, SD59x18_ZERO);

        ...                

        // if account is not liquidatable, skip to next account
        // account is liquidatable if requiredMaintenanceMarginUsdX18 > ctx.marginBalanceUsdX18
        if (!TradingAccount.isLiquidatable(requiredMaintenanceMarginUsdX18, ctx.marginBalanceUsdX18)) {
            continue;
        }

        //@audit => Verify if the account has positive PnL, if so, mint it to the account before proceeding to deduct margin from the account
        if (accountTotalUnrealizedPnlUsdX18.gt(SD59x18_ZERO)) {
            // fetch storage slot for global config
            GlobalConfiguration.Data storage globalConfiguration = GlobalConfiguration.load();
            address usdzToken = globalConfiguration.usdToken;

            uint256 marginToAddX18 = accountTotalUnrealizedPnlUsdX18.intoUD60x18();
            tradingAccount.deposit(usdzToken, marginToAddX18);

            LimitedMintingERC20(usdzToken).mint(address(this), marginToAddX18.intoUint256());
        }

        // deduct maintenance margin from the account's collateral
        // settlementFee = liquidationFee
        ctx.liquidatedCollateralUsdX18 = tradingAccount.deductAccountMargin({
            feeRecipients: FeeRecipients.Data({
                marginCollateralRecipient: globalConfiguration.marginCollateralRecipient,
                orderFeeRecipient: address(0),
                settlementFeeRecipient: globalConfiguration.liquidationFeeRecipient
            }),
            pnlUsdX18: requiredMaintenanceMarginUsdX18,
            orderFeeUsdX18: UD60x18_ZERO,
            settlementFeeUsdX18: ctx.liquidationFeeUsdX18
        });

        ...
    }
}
