        maximumProceeds: DEFAULT_MAXIMUM_PROCEEDS,
        startingTime: block.timestamp + DEFAULT_STARTING_TIME,
        endingTime: block.timestamp + DEFAULT_ENDING_TIME,
        gamma: DEFAULT_GAMMA,
        epochLength: DEFAULT_EPOCH_LENGTH,
