description:
During the liquidation process, BigBang only reduces the user's userBorrowPart[user], but fails to update the global totalBorrow. Consequently, all subsequent debt calculations are incorrect. Currently, the implementation relies on the BBLiquidation._updateBorrowAndCollateralShare() method to calculate user debt repayment and collateral collection. The code snippet is as follows:
```solidity
function _liquidateUser(
address user,
uint256 maxBorrowPart,
IMarketLiquidatorReceiver _liquidatorReceiver,
bytes calldata _liquidatorReceiverData,
uint256 _exchangeRate,
uint256 minLiquidationBonus
) private {
    uint256 callerReward = _getCallerReward(user, _exchangeRate);
    (uint256 borrowAmount,, uint256 collateralShare) =
        _updateBorrowAndCollateralShare(user, maxBorrowPart,
        minLiquidationBonus, _exchangeRate);
    totalCollateralShare = totalCollateralShare > collateralShare ?
        totalCollateralShare - collateralShare : 0;
    uint256 borrowShare = yieldBox.toShare(assetId, borrowAmount, true);
    (uint256 returnedShare,) =
        _swapCollateralWithAsset(collateralShare, _liquidatorReceiver,
        _liquidatorReceiverData);
    if (returnedShare < borrowShare) revert AmountNotValid();
    (uint256 feeShare, uint256 callerShare) =
        _extractLiquidationFees(returnedShare, borrowShare, callerReward);
    IUsdo(address(asset)).burn(address(this), borrowAmount);
    address[] memory _users = new address[](1);
    _users[0] = user;
    emit Liquidated(msg.sender, _users, callerShare, feeShare, borrowAmount,
        collateralShare);
}
function _updateBorrowAndCollateralShare(
    address user,
    uint256 maxBorrowPart,
    uint256 minLiquidationBonus, // min liquidation bonus to accept (default 0)
    uint256 _exchangeRate
) private returns (uint256 borrowAmount, uint256 borrowPart, uint256 collateralShare) {
    if (_exchangeRate == 0) revert ExchangeRateNotValid();
    // get collateral amount in asset's value
    uint256 collateralPartInAsset = (
        yieldBox.toAmount(collateralId, userCollateralShare[user], false) *
        EXCHANGE_RATE_PRECISION
    ) / _exchangeRate;
    // compute closing factor (liquidatable amount)
    uint256 borrowPartWithBonus =
        computeClosingFactor(userBorrowPart[user], collateralPartInAsset,
        FEE_PRECISION_DECIMALS);
    // limit liquidable amount before bonus to the current debt
    uint256 userTotalBorrowAmount =
        totalBorrow.toElastic(userBorrowPart[user], true);
    borrowPartWithBonus = borrowPartWithBonus > userTotalBorrowAmount ?
        userTotalBorrowAmount : borrowPartWithBonus;
    // check the amount to be repaid versus liquidator supplied limit
    borrowPartWithBonus = borrowPartWithBonus > maxBorrowPart ?
        maxBorrowPart : borrowPartWithBonus;
    borrowAmount = borrowPartWithBonus;
    // compute part units, preventing rounding dust when liquidation is full
    borrowPart = borrowAmount == userTotalBorrowAmount
        ? userBorrowPart[user]
        : totalBorrow.toBase(borrowPartWithBonus, false);
    if (borrowPart == 0) revert Solvent();
    if (liquidationBonusAmount > 0) {
        borrowPartWithBonus = borrowPartWithBonus + (borrowPartWithBonus *
        liquidationBonusAmount) / FEE_PRECISION;
    }
    if (collateralPartInAsset < borrowPartWithBonus) {
        if (collateralPartInAsset <= userTotalBorrowAmount) {
            revert BadDebt();
        }
        // If current debt is covered by collateral fully
        // then there is some liquidation bonus,
        // so liquidation can proceed if liquidator's minimum is met
        if (minLiquidationBonus > 0) {
            // `collateralPartInAsset > borrowAmount` as `borrowAmount <= userTotalBorrowAmount`
            uint256 effectiveBonus = ((collateralPartInAsset - borrowAmount)
            * FEE_PRECISION) / borrowAmount;
            if (effectiveBonus < minLiquidationBonus) {
                revert InsufficientLiquidationBonus();
            }
            collateralShare = userCollateralShare[user];
        } else {
            revert InsufficientLiquidationBonus();
        }
    } else {
        collateralShare =
            yieldBox.toShare(collateralId, (borrowPartWithBonus *
            _exchangeRate) / EXCHANGE_RATE_PRECISION, false);
        if (collateralShare > userCollateralShare[user]) {
        }
    }
    userBorrowPart[user] -= borrowPart;
    userCollateralShare[user] -= collateralShare;
}
```
The methods mentioned above update the user-specific variables userBorrowPart[user] and userCollateralShare[user] within the _updateBorrowAndCollateralShare() method. Additionally, the global variable totalCollateralShare is updated within the _liquidateUser() method. However, there's another crucial global variable, totalBorrow, which remains unaltered throughout the entire liquidation process. Failure to update totalBorrow during liquidation will result in incorrect subsequent loan-related calculations. The lack of an update to totalBorrow during liquidation leads to inaccuracies in subsequent loan-related calculations. For instance, this affects interest accumulation and the amount of interest due.

recommendation:
```solidity
function _liquidateUser(
    address user,
    uint256 maxBorrowPart,
    IMarketLiquidatorReceiver _liquidatorReceiver,
    bytes calldata _liquidatorReceiverData,
    uint256 _exchangeRate,
    uint256 minLiquidationBonus
) private {
    uint256 callerReward = _getCallerReward(user, _exchangeRate);
    (uint256 borrowAmount, uint256 borrowPart, uint256 collateralShare) =
        _updateBorrowAndCollateralShare(user, maxBorrowPart,
        minLiquidationBonus, _exchangeRate);
    totalCollateralShare = totalCollateralShare > collateralShare ?
        totalCollateralShare - collateralShare : 0;
    totalBorrow.elastic -= borrowAmount.toUint128();
    totalBorrow.base -= borrowPart.toUint128();
```

description:
Pipeline Convert is a way to convert Silo deposits from one token to another while not losing Grown Stalk and potentially increasing final BDV.

Problem is that it doesn't handle case where final BDV is less than before Pipeline Convert. Because of issue it doesn't decrease Grown Stalk.
It allows users to just withdraw part of their deposit without Grown Stalk penalty.

Let's take a look on pipelineConvert(). It:
Removes deposits from account
Execute Pipeline Convert logic
Creates deposits to account with certain BDV and Grown Stalk which are calculated inside step 2
   <https://github.com/Cyfrin/2024-05-beanstalk-the-finale/blob/df2dd129a878d16d4adc75049179ac0029d9a96b/protocol/contracts/beanstalk/silo/PipelineConvertFacet.sol#L62-L110>
```solidity
    function pipelineConvert(
        address inputToken,
        int96[] calldata stems,
        uint256[] calldata amounts,
        address outputToken,
        AdvancedFarmCall[] calldata advancedFarmCalls
    )
        external
        payable
        fundsSafu
        nonReentrant
        returns (int96 toStem, uint256 fromAmount, uint256 toAmount, uint256 fromBdv, uint256 toBdv)
    {
        ...

        // withdraw tokens from deposits and calculate the total grown stalk and bdv.
        uint256 grownStalk;
        (grownStalk, fromBdv) = LibConvert._withdrawTokens(inputToken, stems, amounts, fromAmount);

        (toAmount, grownStalk, toBdv) = LibPipelineConvert.executePipelineConvert(
            inputToken,
            outputToken,
            fromAmount,
            fromBdv,
            grownStalk,
            advancedFarmCalls
        );

        toStem = LibConvert._depositTokensForConvert(outputToken, toAmount, toBdv, grownStalk);

        emit Convert(LibTractor._user(), inputToken, outputToken, fromAmount, toAmount);
    }
```
Let's dive into step 2. It performs AdvancedFarmCalls and applies penalty to newGrownStalk based on caps and deltaB disbalance.
```solidity
    function executePipelineConvert(
        address inputToken,
        address outputToken,
        uint256 fromAmount,
        uint256 fromBdv,
        uint256 initialGrownStalk,
        AdvancedFarmCall[] calldata advancedFarmCalls
    ) external returns (uint256 toAmount, uint256 newGrownStalk, uint256 newBdv) {
        ...

        IERC20(inputToken).transfer(C.PIPELINE, fromAmount);
        executeAdvancedFarmCalls(advancedFarmCalls);

        // user MUST leave final assets in pipeline, allowing us to verify that the farm has been called successfully.
        // this also let's us know how many assets to attempt to pull out of the final type
        toAmount = transferTokensFromPipeline(outputToken);

        // Calculate stalk penalty using start/finish deltaB of pools, and the capped deltaB is
        // passed in to setup max convert power.
        pipeData.stalkPenaltyBdv = prepareStalkPenaltyCalculation(...);

        // Update grownStalk amount with penalty applied
        newGrownStalk = (initialGrownStalk * (fromBdv - pipeData.stalkPenaltyBdv)) / fromBdv;

        newBdv = LibTokenSilo.beanDenominatedValue(outputToken, toAmount);
    }
```
And in step 3 it calculates new Stem based on Grown Stalk it should produce:
<https://github.com/Cyfrin/2024-05-beanstalk-the-finale/blob/df2dd129a878d16d4adc75049179ac0029d9a96b/protocol/contracts/libraries/Silo/LibTokenSilo.sol#L545-L555>
```solidity
    function calculateStemForTokenFromGrownStalk(
        address token,
        uint256 grownStalk,
        uint256 bdv
    ) internal view returns (int96 stem, GerminationSide side) {
        LibGerminate.GermStem memory germStem = LibGerminate.getGerminatingStem(token);
        stem = germStem.stemTip.sub(
            SafeCast.toInt96(SafeCast.toInt256(grownStalk.mul(PRECISION).div(bdv)))
        );
        side = LibGerminate._getGerminationState(stem, germStem);
    }
```
Finally here is attack vector:
Assume Attacker has Silo deposit of 100e6 Bean with Stem 4990e6. Current stemTip = 5000e6, it means his Grown Stalk is (5000e6 - 4990e6) * 100e6 / 1e6 = 1000e6
In AdvancedFarmCalls during PipelineConvert Attacker just withdraws 99e6 Beans (converts Bean to Bean). It can only slightly be penalised based on cap exceed, penalization doesn't matter so assume penalization doesn't happen
It calculates stem for deposit of 1e6 Bean so that it produced 1000e6 Stalk. As a result user has deposit of 1e6 Bean with stem = 5000e6 - 1000e6 * 1e6 / 1e6 = 4000e6.

As you can see his Grown Stalk was not decreased while user just performed withdrawal via PipelineConvert.

Users can withdraw significant part of their deposit without losing Grown Stalk. And repeat it again and again. This allows to have big amount of Stalk without depositing much to Silo.

Such attacker will steal Roots from fair users without risk. That's because he can make huge deposit for little time to gain huge amount of Stalk and Roots, and then withdraw that huge deposit without Grown Stalk penalization (as far as convert cap allows it).

recommendation:
Decrease Grown Stalk proportionally to decrease of BDV:
```diff
    function executePipelineConvert(
        address inputToken,
        address outputToken,
        uint256 fromAmount,
        uint256 fromBdv,
        uint256 initialGrownStalk,
        AdvancedFarmCall[] calldata advancedFarmCalls
    ) external returns (uint256 toAmount, uint256 newGrownStalk, uint256 newBdv) {
        ...
        // Update grownStalk amount with penalty applied
        newGrownStalk = (initialGrownStalk * (fromBdv - pipeData.stalkPenaltyBdv)) / fromBdv;
        newBdv = LibTokenSilo.beanDenominatedValue(outputToken, toAmount);
        if (newBdv < fromBdv) newGrownStalk = newGrownStalk * newBdv / fromBdv;
    }
```

