function withdrawPrimeCash(
    address account,
    uint16 currencyId,
    int256 primeCashToWithdraw,
    PrimeRate memory primeRate,
    bool withdrawWrappedNativeToken
) internal returns (int256 netTransferExternal) {
    if (primeCashToWithdraw == 0) return 0;
    require(primeCashToWithdraw < 0);

    Token memory underlying = getUnderlyingToken(currencyId);
    netTransferExternal = convertToExternal(
        underlying,
        primeRate.convertToUnderlying(primeCashToWithdraw)
    );

    // Overflow not possible due to int256
    uint256 withdrawAmount = uint256(netTransferExternal.neg());
    _redeemMoneyMarketIfRequired(currencyId, underlying, withdrawAmount);

    if (underlying.tokenType == TokenType.Ether) {
        GenericToken.transferNativeTokenOut(account, withdrawAmount, withdrawWrappedNativeToken);
    } else {
        GenericToken.safeTransferOut(underlying.tokenAddress, account, withdrawAmount);
    }

    _postTransferPrimeCashUpdate(account, currencyId, netTransferExternal, underlying, primeRate);
}
```
It's likely that the vault account is considered solvent in this case, but due to the inability to trade between currencies, it is not possible to use excess cash in one currency to offset debt in another.
Liquidations require vaults to be settled if block.timestamp is past the maturity date, hence, it is not possible to deleverage vault accounts, leading to bad debt accrual.

In LenderActions's moveQuoteToken() LUP is being evaluated after liquidity removal, but before liquidity addition. This intermediary LUP doesn't correspond to target utilization and interest rate calculations.
moveQuoteToken() calculates LUP after deposit removal only instead of doing so after the whole operation, being atomic removal from one index and addition to another, and then updates the pool accounting _updateInterestState(poolState, the pool.
moveQuoteToken() is one of the base frequently used operations, so the state of the pool will be frequently enough updated with incorrect LUP and EMA of LUP * t0 debt internal accounting variable be systematically biased, which leads to incorrect interest rate dynamics of the pool.
There is no low-probability prerequisites and the impact is a bias in interest rate calculations, so setting the severity to be high.
moveQuoteToken() calculates the LUP right after the deposit removal:
external/LenderActions.sol#L237-L312
```solidity
function moveQuoteToken(
    mapping(uint256 => Bucket) storage buckets_,
    DepositsState storage deposits_,
    PoolState calldata poolState_,
    MoveQuoteParams calldata params_
) external returns (uint256 fromBucketRedeemedLP_, uint256 toBucketLP_, uint256 movedAmount_, uint256 lup_) {
    ...
    (movedAmount_, fromBucketRedeemedLP_, vars.fromBucketRemainingDeposit) =
        _removeMaxDeposit(
            deposits_,
            RemoveDepositParams({
                depositConstraint: params_.maxAmountToMove,
                lpConstraint: vars.fromBucketLenderLP,
                bucketLP: vars.fromBucketLP,
                bucketCollateral: vars.fromBucketCollateral,
                price: vars.fromBucketPrice,
                index: params_.fromIndex,
                dustLimit: poolState_.quoteTokenScale
            })
        );
    lup_ = Deposits.getLup(deposits_, poolState_.debt);
    // apply unutilized deposit fee if quote token is moved from above it
    if (vars.fromBucketPrice >= lup_ && vars.toBucketPrice < lup_) {
        movedAmount_ = Maths.wmul(movedAmount_, Maths.WAD - _depositFeeRate(poolState_.rate));
    }
    vars.toBucketUnscaledDeposit = Deposits.unscaledValueAt(deposits_, params_.toIndex);
    vars.toBucketScale = Deposits.scale(deposits_, params_.toIndex);
    vars.toBucketDeposit = Maths.wmul(vars.toBucketUnscaledDeposit, vars.toBucketScale);
    toBucketLP_ = Buckets.quoteTokensToLP(
        toBucket.collateral,
        toBucket.lps,
        vars.toBucketDeposit,
        movedAmount_,
        vars.toBucketPrice,
        Math.Rounding.Down
    );
    // revert if (due to rounding) the awarded LP in to bucket is 0
    if (toBucketLP_ == 0) revert InsufficientLP();
    Deposits.unscaledAdd(deposits_, params_.toIndex, Maths.wdiv(movedAmount_, vars.toBucketScale));
    vars.htp = Maths.wmul(params_.thresholdPrice, poolState_.inflator);
    // check loan book's htp against new lup, revert if move drives LUP below HTP
    if (params_.fromIndex < params_.toIndex && vars.htp > lup_) revert LUPBelowHTP();
