            if (fBalance - iBalance != 0) ss.oAmount = fBalance - iBalance;
            _verifyStablecoinSwap(wallet, ss);
            _stablecoinSwap(wallet, ss);
        }
    } else {
        // if stablecoin swap
        _stablecoinSwap(wallet, ss);
        // if only stablecoin swap
        if (defi.walletData.length != 0) _defiSwap(wallet, defi);
