Consider the following -->
1.) Victim has deposited into the LendingAssetVault.sol (what we call the Meta Vault), let's say when the victim deposited the block.number = 50 i.e. _lastDeposit[victim] = 50
2.) Now at block 80 the victim wants to withdraw, he calls the withdraw function providing the assets he wants to withdraw.
3.) The attacker sees this tx in the mempool, frontruns the withdraw call of the victim and calls the deposit function with just 1 wei of assets, (or the minimum amount required so that the shares are non-zero) and sets the victim's address as the receiver address -->
```solidity
function deposit(uint256 _assets, address _receiver) external override returns (uint256 _shares) {
    _updateInterestAndMdInAllVaults(address(0));
    _shares = convertToShares(_assets);
    _deposit(_assets, _shares, _receiver);
}
```
this would update the victim's _lastDeposit[victim] to 80 here -->
```solidity
function _deposit(
    uint256 _assets,
    uint256 _shares,
    address _receiver
) internal {
    require(_assets != 0 && _shares != 0, "M");
    _totalAssets += _assets;
    _lastDeposit[_receiver] = block.number; <-- here
    _mint(_receiver, _shares);
    IERC20(_asset).safeTransferFrom(_msgSender(), address(this), _assets);
    emit Deposit(_msgSender(), _receiver, _assets, _shares);
}
```
4.) Now when the victim's withdraw tx executes it would revert due to this check in the _withdraw call -->
```solidity
require(!_lastDepEnabled || block.number > _lastDeposit[_owner], "MIN");
```
L178 of LendingAssetVault.sol
Therefore, as long as the attacker performs this frontrunning the victim can not withdraw his assets back from the vault which would mean a permanent freeze of those assets.

The commitToMint function in the contract allows signatures signed by the signer to be replayed using different addresses. Anyone can see the signatures on-chain and then replay them with different accounts that have the same nonce. An attacker can start inputting previous signatures submitted by a user starting from a nonce of 0 until the current one.
```solidity
/// @param _collectionId The Id of the collection you wish to roll for
/// @param spins The amount of spins you wish to roll
/// @param signature A signature commit to the price, nonce, and minter from the
// authority address
/// @return ticketNonce The nonce to use to claim your mint
function commitToMint(
uint256 _collectionId,
uint256 spins,
address minter,
bytes memory signature
) public payable returns (uint256 ticketNonce)
{
if (msg.sender != commitController) {
uint256 nonce = userNonce[msg.sender];
bytes32 hash = keccak256(abi.encodePacked
(_collectionId, spins, nonce, msg.value, minter));
bytes32 signedHash = hash.toEthSignedMessageHash();
address approved = ECDSA.recover(signedHash, signature);
if (approved != signer) {
revert NotApproved();
}
if (msg.value != 0) {
payable(protocolFeeTo).transfer(msg.value);
}
ticketNonce = rng.rng();
NonceData memory data = NonceData({ owner: minter, collectionId: uint128
(_collectionId), spins: uint128(spins) });
uint256 _userNonce = userNonce[msg.sender];
userNonce[msg.sender] = _userNonce + 1;
dataOf[ticketNonce] = data;
emit MintCommited
(msg.sender, minter, spins, msg.value, _userNonce + 1, ticketNonce);
}
```

```solidity
function _pendingTPS(StorageStaking storage $) private view returns (uint256) {
    if ($.totalDeposited == 0) return $.tps;
    /* solhint-disable-next-line not-rely-on-time */
    uint256 secondsPassed = block.timestamp - $.lastCheckpoint;
    // We need double rounding here to avoid situations where borrowers repay less
    // than what is due to lenders. With division in formulas, a surplus is unavoidable,
    // but it must favor the pool and not the lender, because in the latter case
    // we simply cannot pay off.
    uint256 r1 = ($.apy * secondsPassed * $.utilization) / (APY_DENOMINATOR * 365 days);
    uint256 r2 = (r1 * TPS_DENOMINATOR) / $.totalDeposited;
    return $.tps + r2;
}

function _pendingInterest(
    StorageStaking storage $,
    address borrower
) private view returns (uint256) {
    Debt storage debt = $.debts[borrower];
    /* solhint-disable-next-line not-rely-on-time */
    uint256 secondsPassed = block.timestamp - debt.timestamp;
    return (debt.borrowed * secondsPassed * $.apy) / (APY_DENOMINATOR * 365 days);
}
```
The problem arises when the APY is changed:
```solidity
function _setApy(uint32 apy) internal {
    _setApy(_storageStaking(), apy);
}
// ...
function _setApy(StorageStaking storage $, uint32 apy) private {
    $.apy = apy;
}
```
No checkpoint is made before applying the new APY, it affects all interest retroactively from the last checkpoint. This results in unfair interest accumulation: • For lenders: Their rewards calculation via TPS will be retroactively changed. • For borrowers: The interest on their loans will be calculated using the new rate for the entire loan period.

Some ERC20 tokens are expected to be blocked in the contract with the onlyUnblockedTokens modifier, and the owner shouldn't be able to withdraw them. That's the reason this check is implemented for withdrawERC20():
```solidity
function withdrawERC20(
    address _token,
    uint256 _amount
) external onlyUnblockedTokens(_token)
```
```solidity
modifier onlyUnblockedTokens(address _token) {
    if (!unlocked && HONEY_QUEEN.isTokenBlocked(_token)) revert TokenBlocked();
}
```
The issue lies in that it is possible to withdraw those ERC20 tokens via the withdrawLPToken() function:
```solidity
function withdrawLPToken(address _LPToken, uint256 _amount) external onlyOwner {
    if (expirations[_LPToken] == 0) revert HasToBeLPToken();
    if (block.timestamp < expirations[_LPToken]) revert NotExpiredYet();
    ERC20(_LPToken).transfer(msg.sender, _amount);
}
```
The function implements a expirations[_LPToken] == 0 check to prevent non-LP tokens from being withdrawn, but this expectation can be broken by calling depositAndLock() with the token, a zero-amount value, and a past expiration:
```solidity
function depositAndLock(
    address _LPToken,
    uint256 _amountOrId,
    uint256 _expiration
) external onlyOwnerOrMigratingVault {
    if (!unlocked && expirations[_LPToken] != 0 && _expiration < expirations[_LPToken])
        revert ExpirationNotMatching();
    expirations[_LPToken] = unlocked ? 1 : _expiration;
    ERC721(_LPToken).transferFrom(msg.sender, address(this), _amountOrId);
}
```
This way, the contract owner can set a non-zero past expirations[_LPToken] value. This will allow them to withdraw blocked tokens.

The existing control to prevent ETH from being sold during reinvestment can be bypassed, allowing the bots to accidentally or maliciously sell off the non-reward assets of the vault.

Multiple instances of this issue were found:

Instance 1 - Curve's Implementation
The _isInvalidRewardToken function attempts to prevent the callers from selling away ETH during reinvestment.
ontracts/vaults/curve/ConvexStakingMixin.sol#L60
File: ConvexStakingMixin.sol
```solidity
function _isInvalidRewardToken(address token) internal override view returns (bool) {
    return (
        token == TOKEN_1 ||
        token == TOKEN_2 ||
        token == address(CURVE_POOL_TOKEN) ||
        token == address(CONVEX_REWARD_POOL) ||
        token == address(CONVEX_BOOSTER) ||
        token == Deployments.ALT_ETH_ADDRESS
    );
}
```
However, the code at Line 67 above will not achieve the intended outcome as Deployments.ALT_ETH_ADDRESS is not a valid token address in the first place.
```solidity
address internal constant ALT_ETH_ADDRESS = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;
```
When the caller is executing a trade with ETH, the address for ETH used is either Deployments.WETH or Deployments.ETH_ADDRESS (address(0)) as shown in the TradingUtils's source code, not the Deployments.ALT_ETH_ADDRESS.
ontracts/trading/TradingUtils.sol#L128
File: TradingUtils.sol
```solidity
function _executeTrade(
    address target,
    uint256 msgValue,
    bytes memory params,
    address spender,
    Trade memory trade
) private {
    uint256 preTradeBalance;

    if (trade.buyToken == address(Deployments.WETH)) {
        preTradeBalance = address(this).balance;
    } else if (trade.buyToken == Deployments.ETH_ADDRESS || _needsToUnwrapExcessWETH(trade, spender)) {
        preTradeBalance = IERC20(address(Deployments.WETH)).balanceOf(address(this));
